AppState* gAppState{};
gameplay::bot::NavigationGraph& activeBotNavigation(AppState& app){
    // Custom authoring owns its graph. Imported records remain separately
    // owned and are a fallback only while no custom navigation is present.
    const auto& g=app.botNavigation;
    return !g.nodes.empty()||!g.links.empty()||!g.blocks.empty()||!g.goalAreas.empty()||g.boundary.enabled?app.botNavigation:app.mapActiveAuthoredNavigation;
}
void refreshAuthoredMapNavigation(AppState& app){
    app.mapActiveAuthoredNavigation={};const auto& source=app.mapAuthoredNavigation.graph;
    if(app.mapUseAuthoredGuidance){app.mapActiveAuthoredNavigation.nodes=source.nodes;app.mapActiveAuthoredNavigation.links=source.links;}
    if(app.mapUseAuthoredGoals)app.mapActiveAuthoredNavigation.goalAreas=source.goalAreas;
    if(app.mapUseAuthoredLimits){app.mapActiveAuthoredNavigation.blocks=source.blocks;app.mapActiveAuthoredNavigation.boundary=source.boundary;}
    for(auto& bot:app.bots){bot.navigation=app.botUseAuthoredNavigation?&activeBotNavigation(app):nullptr;bot.navigationRoute.clear();bot.repathTime=0;}
    app.botSpRoutes.clear();app.botSpawnHistory={};app.botAreaPing.clear();
}
