void logLoading(AppState& app, std::string_view msg, float progress = -1.0f) {
    const double elapsed = app.loadingStartTime > 0.0 ? (glfwGetTime() - app.loadingStartTime) : 0.0;
    char timeBuf[32];
    std::snprintf(timeBuf, sizeof(timeBuf), "[%5.2fs] ", elapsed);
    const std::string fullMsg = std::string(timeBuf) + std::string(msg);
    {
        std::lock_guard<std::mutex> lock(app.loadingLogMutex);
        app.loadingLogs.push_back(fullMsg);
        if (progress >= 0.0f) {
            app.loadingProgress = progress;
        }
    }
    std::cout << fullMsg << std::endl;
}

bool uploadMainScene(AppState& app, render::ProgressCallback progressCallback = nullptr){
    app.renderer.setMapTextureResolution(app.mapTextureResolution);
    app.renderer.setHardwareTextureCompression(app.mapTextureCompression);
    app.classGpuResident=false;app.rendererError.clear();
    if(app.mapGpuReady && app.loadedMap && app.renderer.hasMapMeshes()){
        const bool mainReady = app.renderer.replaceMainScene(app.scene, app.hiddenWorldActor ? &*app.hiddenWorldActor : nullptr, app.botActorScene ? &*app.botActorScene : nullptr, app.rendererError);
        app.worldActorGpuReady = mainReady && app.hiddenWorldActor.has_value();
        app.botActorGpuReady = mainReady && app.botActorScene.has_value();
        return mainReady;
    }
    const bool mainReady=app.renderer.loadScene(app.scene,app.rendererError);app.botActorGpuReady=false;app.worldActorGpuReady=false;app.mapGpuReady=false;
    if(mainReady&&(app.loadedMap||app.hiddenWorldActor||app.botActorScene)){std::string actorError;const bool actorsReady=app.renderer.loadAuxiliaryScenes(app.loadedMap?&app.loadedMap->scene:nullptr,app.hiddenWorldActor?&*app.hiddenWorldActor:nullptr,app.botActorScene?&*app.botActorScene:nullptr,actorError,progressCallback);app.mapGpuReady=actorsReady&&app.loadedMap.has_value();app.worldActorGpuReady=actorsReady&&app.hiddenWorldActor.has_value();app.botActorGpuReady=actorsReady&&app.botActorScene.has_value();if(!actorsReady&&app.rendererError.empty())app.rendererError=actorError;}
    return mainReady;
}

bool uploadResidentClassScenes(AppState& app){
    app.renderer.setMapTextureResolution(app.mapTextureResolution);
    app.renderer.setHardwareTextureCompression(app.mapTextureCompression);
    if(!app.classSlotRigs[0]||!app.classSlotRigs[1])return false;
    const auto& primary=app.activeClassSlot==0?app.scene:app.classSlotRigs[0]->scene;
    const auto& secondary=app.activeClassSlot==1?app.scene:app.classSlotRigs[1]->scene;
    const auto* primaryWorld=app.activeClassSlot==0?(app.hiddenWorldActor?&*app.hiddenWorldActor:nullptr):(app.classSlotRigs[0]->worldActor?&*app.classSlotRigs[0]->worldActor:nullptr);
    const auto* secondaryWorld=app.activeClassSlot==1?(app.hiddenWorldActor?&*app.hiddenWorldActor:nullptr):(app.classSlotRigs[1]->worldActor?&*app.classSlotRigs[1]->worldActor:nullptr);
    const auto* third=app.classSlotRigs[2]?(app.activeClassSlot==2?&app.scene:&app.classSlotRigs[2]->scene):nullptr;
    const auto* thirdWorld=app.classSlotRigs[2]?(app.activeClassSlot==2?(app.hiddenWorldActor?&*app.hiddenWorldActor:nullptr):(app.classSlotRigs[2]->worldActor?&*app.classSlotRigs[2]->worldActor:nullptr)):nullptr;
    app.rendererError.clear();
    const bool hasMap = app.mapGpuReady && app.loadedMap && app.renderer.hasMapMeshes();
    const bool ready = hasMap
        ? app.renderer.replaceClassScenes(primary, secondary, primaryWorld, secondaryWorld, app.botActorScene ? &*app.botActorScene : nullptr, app.rendererError,third,thirdWorld)
        : app.renderer.loadClassScenes(primary, secondary, primaryWorld, secondaryWorld, app.loadedMap ? &app.loadedMap->scene : nullptr, app.botActorScene ? &*app.botActorScene : nullptr, app.rendererError,third,thirdWorld);
    app.classGpuResident=ready;
    if(ready)app.renderer.setActiveClassSlot(std::max(0,app.activeClassSlot));
    app.mapGpuReady=ready&&app.loadedMap.has_value();
    app.worldActorGpuReady=ready&&(primaryWorld||secondaryWorld||thirdWorld);
    app.botActorGpuReady=ready&&app.botActorScene.has_value();
    return ready;
}

float actorGroundHeight(const AppState& app,float x,float y,float referenceZ){return app.loadedMap?app.loadedMap->navigationGroundHeight(x,y,referenceZ,-1e9f,scene::course::kPlayerRadius*0.75f):scene::course::groundHeight(x,y);}
scene::Vec3 localNavigationGround(const AppState& app,scene::Vec3 position){
    // Map ground queries include a legacy +45 cm allowance. Cancel it: a
    // spawn/node at the player's feet must not select the roof above them.
    const float ground=actorGroundHeight(app,position.x,position.y,position.z+2.f-45.f);
    if(std::isfinite(ground)&&ground>-1e8f&&position.z-ground<=scene::course::kStepHeight+2.f)position.z=ground;
    return position;
}
scene::Vec3 constrainActorMove(const AppState& app,scene::Vec3 oldPosition,scene::Vec3 proposed,scene::Vec3* outContactNormal = nullptr){return app.loadedMap?app.loadedMap->constrainMove(oldPosition,proposed,scene::course::kPlayerRadius,gameplay::iw::worldUnits(app.gameplayStance==scene::Stance::Stand?72.f:app.gameplayStance==scene::Stance::Crouch?40.f:20.f),scene::course::kStepHeight,outContactNormal):scene::course::constrainMove(oldPosition,proposed);}

