            const bool adsOwnsCamera=app.gameplayAds||app.viewmodelAdsEngaged||app.viewmodelAdsExiting||app.viewmodelAdsPoseHold;
            const bool preserveAuthoredCamera=hasCameraBone&&!app.actorMantling;
            if(!preserveAuthoredCamera){
                app.actorViewCamera.v[0]=forward.x;app.actorViewCamera.v[1]=forward.y;app.actorViewCamera.v[2]=forward.z;
                app.actorViewCamera.v[4]=lateral.x;app.actorViewCamera.v[5]=lateral.y;app.actorViewCamera.v[6]=lateral.z;
                app.actorViewCamera.v[8]=up.x;app.actorViewCamera.v[9]=up.y;app.actorViewCamera.v[10]=up.z;
                app.actorViewCamera.v[12]=desiredCamera.v[12];app.actorViewCamera.v[13]=desiredCamera.v[13];app.actorViewCamera.v[14]=desiredCamera.v[14];
            }
            const auto cameraBoost=gameplay::view::motionTransform(app.boostCamera,app.boostCameraElapsed,gameplay::iw::worldUnits(1.f));
            const auto tilt=scene::rotation(scene::fromEulerRadians(app.directionalTiltDegrees*(scene::kPi/180.f)));
            const auto cameraFeedback=cameraBoost*(app.directionalTilt.camera?tilt:scene::Mat4::identity());
            const auto rigFeedback=(app.boostCameraMovesViewmodel?cameraBoost:scene::Mat4::identity())*(app.directionalTilt.viewmodel?tilt:scene::Mat4::identity());
            const auto worldRigFeedback=desiredCamera*rigFeedback*scene::inverseAffine(desiredCamera);
            app.viewmodelRigAnchor=worldRigFeedback*app.viewmodelRigAnchor;
