                desiredCamera.v[4]=lateral.x;desiredCamera.v[5]=lateral.y;desiredCamera.v[6]=lateral.z;
                desiredCamera.v[8]=up.x;desiredCamera.v[9]=up.y;desiredCamera.v[10]=up.z;
                desiredCamera.v[12]=effectiveActorPos.x;desiredCamera.v[13]=effectiveActorPos.y;desiredCamera.v[14]=(app.actorPresentationZValid?app.actorPresentationZ:effectiveActorPos.z)+app.actorViewHeight;
