void advanceAnimationFrame(AppState& app,float& frame,const scene::Animation& animation,float delta,bool allowLoop=true){
    const float prevFrame=frame;
    frame+=delta*animation.framerate;
    if(app.muzzleFlashNotetracks&&!isKnifeWeapon(app)&&delta>0.0f){
        for(const auto& notif:animation.notifications){
            const auto nameLower=lowerText(notif.name);
            if(notif.kind==scene::NotetrackKind::Fire||notif.kind==scene::NotetrackKind::MuzzleFlash||
               nameLower.find("fire")!=std::string::npos||nameLower.find("shoot")!=std::string::npos||
               nameLower.find("flash")!=std::string::npos||nameLower.find("muzzle")!=std::string::npos){
                for(const auto f:notif.frames){
                    const float nf=static_cast<float>(f);
                    if((prevFrame<=nf&&frame>=nf)||(frame<prevFrame&&(nf>=prevFrame||nf<=frame))){
                        app.playerMuzzleFlashTime=app.muzzleFlashDuration;
                        app.playerMuzzleFlashRotation=app.muzzleFlashRandomRotation?((std::rand()%360)*(scene::kPi/180.0f)):(app.muzzleFlashRotationAngle*scene::kPi/180.0f);
                        if(app.smokeTrailEnabled)app.smokeEmissionCooldown=app.smokeEmissionDuration;
                        break;
                    }
                }
            }
        }
    }
    if(frame>animation.durationFrames)frame=allowLoop&&animation.looping&&animation.durationFrames?std::fmod(frame,static_cast<float>(animation.durationFrames)):static_cast<float>(animation.durationFrames);
}

void drawPlayback(AppState& app) {
    if (app.scene.animations.empty()) {
        ImGui::BeginDisabled(); ImGui::Button("Play"); ImGui::SameLine(); ImGui::TextUnformatted("No animation clips"); ImGui::EndDisabled();
        return;
    }
    if (ImGui::Button(app.playing ? "Pause" : "Play")) app.playing = !app.playing;
    ImGui::SameLine();
    ImGui::SetNextItemWidth(190);
    const auto clipLabel=[](const scene::Animation& clip){
        const auto name=clip.name.empty()?std::string("<unnamed animation>"):clip.name;
        return std::string("[")+scene::animationRoleName(clip.role)+"] "+name+" — "+clip.sourceName+" ("+std::to_string(clip.tracks.size())+" tracks)";
    };
    const auto preview=clipLabel(app.scene.animations[app.animationIndex]);
    ImGui::BeginDisabled(app.gameplayLogic);
    if (ImGui::BeginCombo("##clip", preview.c_str())) {
        for (std::size_t i=0;i<app.scene.animations.size();++i) {
            if(!matchesAnimationFilter(app,app.scene.animations[i]))continue;
            ImGui::PushID(static_cast<int>(i));
            const auto label=clipLabel(app.scene.animations[i]);
            if (ImGui::Selectable(label.c_str(), i==app.animationIndex)) {
                const auto& candidate=app.scene.animations[i];
                if(candidate.domain==scene::AnimationDomain::ViewModel&&candidate.action==scene::ActionRole::Aim)startViewmodelAimClip(app,i);
                else{app.actionActive=false;app.actionOverlay=false;app.activeAction=scene::ActionRole::None;app.viewmodelAdsEngaged=app.viewmodelAdsExiting=false;app.viewmodelAdsBaseAnimation=static_cast<std::size_t>(-1);selectAnimation(app,i);}
            }
            ImGui::PopID();
        }
        ImGui::EndCombo();
    }
    ImGui::EndDisabled();
    ImGui::SameLine();
    const auto& animation=app.scene.animations[app.animationIndex];
    ImGui::SetNextItemWidth(220);
    ImGui::SliderFloat("Frame", &app.animationFrame, 0.0f, static_cast<float>(animation.durationFrames), "%.2f");
    ImGui::SameLine(); ImGui::SetNextItemWidth(85); ImGui::DragFloat("Speed", &app.playbackSpeed, 0.05f, 0.0f, 4.0f, "%.2fx");
}

