std::size_t findGenericPlayermodelForGame(const AppState& app, const std::string& gameName) {
    if (gameName.empty()) return static_cast<std::size_t>(-1);
    const auto gLower = lowerText(gameName);
    const auto setupIt = app.gameReferenceSetups.find(gameName);
    if (setupIt != app.gameReferenceSetups.end() && setupIt->second.playermodelAsset < app.assetCatalog.entries.size()) {
        const auto& candidate = app.assetCatalog.entries[setupIt->second.playermodelAsset];
        if (candidate.role == assets::Role::PlayerModel && lowerText(candidate.game) == gLower) {
            return setupIt->second.playermodelAsset;
        }
    }
    std::size_t bestIdx = static_cast<std::size_t>(-1);
    int bestScore = -1;
    for (std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i) {
        const auto& asset = app.assetCatalog.entries[i];
        if (asset.role != assets::Role::PlayerModel || lowerText(asset.game) != gLower) continue;
        const auto name = lowerText(asset.name);
        int score = 1;
        if (name.find("_fb") != std::string::npos || name.find("fullbody") != std::string::npos) score += 50;
        if (name.find("assault") != std::string::npos || name.find("rifle") != std::string::npos) score += 20;
        if (name.find("seal6") != std::string::npos || name.find("delta") != std::string::npos || name.find("ghosts") != std::string::npos || name.find("atlas") != std::string::npos || name.find("sas") != std::string::npos) score += 15;
        if (name.find("body") != std::string::npos) score += 10;
        if (score > bestScore) {
            bestScore = score;
            bestIdx = i;
        }
    }
    return bestIdx;
}

std::size_t findGenericHeadForPlayermodel(const AppState& app, const std::string& gameName, const assets::Asset& bodyAsset) {
    const auto name = lowerText(bodyAsset.name);
    if (name.find("_fb") != std::string::npos || name.find("fullbody") != std::string::npos) return static_cast<std::size_t>(-1);
    const auto gLower = lowerText(gameName);
    const auto setupIt = app.gameReferenceSetups.find(gameName);
    if (setupIt != app.gameReferenceSetups.end() && setupIt->second.headAsset < app.assetCatalog.entries.size()) {
        const auto& candidate = app.assetCatalog.entries[setupIt->second.headAsset];
        if (lowerText(candidate.game) == gLower&&assets::character::headCompatible(gLower,bodyAsset.name,candidate.name)) return setupIt->second.headAsset;
    }
    std::size_t bestIdx = static_cast<std::size_t>(-1);
    int bestScore = -1;
    for (std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i) {
        const auto& asset = app.assetCatalog.entries[i];
        if (lowerText(asset.game) != gLower) continue;
        const auto cname = lowerText(asset.name);
        if (!assets::character::headCompatible(gLower,bodyAsset.name,cname)) continue;
        int score = 1;
        if (cname.find("head_mp") != std::string::npos || cname.find("mp_head") != std::string::npos) score += 30;
        for (const auto& key : bodyAsset.compatibilityKeys) {
            if (std::find(asset.compatibilityKeys.begin(), asset.compatibilityKeys.end(), key) != asset.compatibilityKeys.end()) {
                score += 10;
            }
        }
        if (score > bestScore) {
            bestScore = score;
            bestIdx = i;
        }
    }
    return bestIdx;
}

