std::size_t findGenericViewhandsForGame(const AppState& app, const std::string& gameName) {
    if (gameName.empty()) return static_cast<std::size_t>(-1);
    const auto gLower = lowerText(gameName);
    const auto setupIt = app.gameReferenceSetups.find(gameName);
    if (setupIt != app.gameReferenceSetups.end() && setupIt->second.viewhandsAsset < app.assetCatalog.entries.size()) {
        const auto& candidate = app.assetCatalog.entries[setupIt->second.viewhandsAsset];
        if (candidate.role == assets::Role::ViewHands && lowerText(candidate.game) == gLower) {
            return setupIt->second.viewhandsAsset;
        }
    }
    std::size_t bestIdx = static_cast<std::size_t>(-1);
    int bestScore = -1;
    for (std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i) {
        const auto& asset = app.assetCatalog.entries[i];
        if (asset.role != assets::Role::ViewHands || lowerText(asset.game) != gLower) continue;
        const auto name = lowerText(asset.name);
        int score = 1;
        if (name.find("viewmodel_base_viewhands") != std::string::npos || name.find("base_viewhands") != std::string::npos) score += 50;
        if ((gLower=="iw_sp"||gLower=="iw7"||gLower=="iw")&&name.find("viewmodel_base_viewhands_iw7")!=std::string::npos) score += 100;
        if (name.find("longsleeve") != std::string::npos) score += 40;
        if (name.find("seal6") != std::string::npos || name.find("ghosts") != std::string::npos || name.find("delta") != std::string::npos) score += 20;
        if (name.find("viewhands") != std::string::npos) score += 10;
        if (score > bestScore) {
            bestScore = score;
            bestIdx = i;
        }
    }
    return bestIdx;
}

