void mountGenericPlayermodel(AppState& app, const std::string& gameName) {
    const auto playerAssetIdx = findGenericPlayermodelForGame(app, gameName);
    if (playerAssetIdx >= app.assetCatalog.entries.size()) {
        app.status = "No generic playermodel found for [" + gameName + "]";
        return;
    }
    const auto& playerAsset = app.assetCatalog.entries[playerAssetIdx];
    const auto sources = app.animationSources;
    auto documents = std::move(app.animationDocuments);
    loadFile(app, playerAsset.path);
    app.animationSources = sources;
    app.animationDocuments = std::move(documents);

    const auto setupIt = app.gameReferenceSetups.find(gameName);
    const auto appendIfValid = [&](std::size_t assetIdx){
        if(assetIdx < app.assetCatalog.entries.size()){
            addRigModelFile(app, app.assetCatalog.entries[assetIdx].path, false);
        }
    };

    for(auto part:characterAssemblyParts(app,playerAsset))appendIfValid(part);

    finishRigMerge(app);
    app.activeReferenceMode = AppState::ReferenceRigMode::Playermodel;
    app.selectedBaseAsset = playerAssetIdx;
    app.assetFirstPerson = false;
    app.status = "Mounted verified playermodel rig for [" + gameName + "] (" + playerAsset.name + ")";
}

void ensurePlayermodelMounted(AppState& app, const std::string& gameName) {
    const auto playerAssetIdx = findGenericPlayermodelForGame(app, gameName);
    if (playerAssetIdx >= app.assetCatalog.entries.size()) return;
    if (app.activeReferenceMode == AppState::ReferenceRigMode::Playermodel && app.selectedBaseAsset == playerAssetIdx && !app.scene.meshes.empty()) {
        return; // Already mounted! Instant playback without disk reload.
    }
    if (app.activeReferenceMode == AppState::ReferenceRigMode::Dual && !app.scene.meshes.empty()) {
        return; // Dual rig already includes playermodel! Instant playback.
    }
    mountGenericPlayermodel(app, gameName);
}

void mountGenericViewmodel(AppState& app, const std::string& gameName) {
    const auto handsIdx = findGenericViewhandsForGame(app, gameName);
    const auto weaponIdx = findGenericViewWeaponForGame(app, gameName);
    if (handsIdx >= app.assetCatalog.entries.size()) {
        app.status = "No generic viewhands found for [" + gameName + "]";
        return;
    }
    app.selectedBaseAsset = handsIdx;
    app.assetFirstPerson = true;

    if (weaponIdx < app.assetCatalog.entries.size()) {
        app.selectedWeaponAsset = weaponIdx;
        equipViewWeapon(app, weaponIdx);
    } else {
        const auto sources = app.animationSources;
        auto documents = std::move(app.animationDocuments);
        loadFile(app, app.assetCatalog.entries[handsIdx].path);
        app.animationSources = sources;
        app.animationDocuments = std::move(documents);
        reloadAnimationSources(app);
    }
    app.activeReferenceMode = AppState::ReferenceRigMode::Viewmodel;
    app.status = "Mounted verified viewmodel rig for [" + gameName + "] (" + app.assetCatalog.entries[handsIdx].name + ")";
}

void mountGenericDualRig(AppState& app, const std::string& gameName) {
    const auto playerAssetIdx = findGenericPlayermodelForGame(app, gameName);
    const auto handsIdx = findGenericViewhandsForGame(app, gameName);
    const auto weaponIdx = findGenericViewWeaponForGame(app, gameName);

    if (playerAssetIdx >= app.assetCatalog.entries.size() && handsIdx >= app.assetCatalog.entries.size()) {
        app.status = "No reference models found for [" + gameName + "]";
        return;
    }

    const auto sources = app.animationSources;
    auto documents = std::move(app.animationDocuments);

    if (playerAssetIdx < app.assetCatalog.entries.size()) {
        const auto& playerAsset = app.assetCatalog.entries[playerAssetIdx];
        loadFile(app, playerAsset.path);

        for (auto& bone : app.scene.skeleton.bones) {
            if (bone.parent < 0) {
                bone.restLocal.position.x -= 30.0f;
            }
        }

        for(const auto part:characterAssemblyParts(app,playerAsset))
            addRigModelFile(app, app.assetCatalog.entries[part].path, false);

        if (handsIdx < app.assetCatalog.entries.size()) {
            const auto& handsAsset = app.assetCatalog.entries[handsIdx];
            auto handsDoc = cast::Document::load(handsAsset.path);
            if (handsDoc.valid()) {
                const auto beforeBones = app.scene.skeleton.bones.size();
                scene::appendRigModel(handsDoc, app.scene, handsAsset.name);
                for (std::size_t b = beforeBones; b < app.scene.skeleton.bones.size(); ++b) {
                    if (app.scene.skeleton.bones[b].parent < 0) {
                        app.scene.skeleton.bones[b].restLocal.position.x += 30.0f;
                        app.scene.skeleton.bones[b].restLocal.position.z += 40.0f;
                    }
                }
                app.loadedRigModelPaths.push_back(handsAsset.path);

                if (weaponIdx < app.assetCatalog.entries.size()) {
                    const auto& weaponAsset = app.assetCatalog.entries[weaponIdx];
                    addRigModelFile(app, weaponAsset.path, false);
                    for (const auto index : app.assetCatalog.compatibleAttachments(weaponIdx)) {
                        if (shouldAutoLoadRigPart(app,weaponAsset, app.assetCatalog.entries[index])) {
                            addRigModelFile(app, app.assetCatalog.entries[index].path, false);
                        }
                    }
                }
            }
        }
        finishRigMerge(app);
    } else if (handsIdx < app.assetCatalog.entries.size()) {
        mountGenericViewmodel(app, gameName);
        return;
    }

    app.animationSources = sources;
    app.animationDocuments = std::move(documents);
    reloadAnimationSources(app);

    app.activeReferenceMode = AppState::ReferenceRigMode::Dual;
    app.status = "Mounted Dual Reference Rig (Playermodel + Viewmodel) for [" + gameName + "]";
}

std::filesystem::path gameRootDirectoryForGame(const AppState& app, const std::string& gameName) {
    if (gameName.empty()) return {};
    for (const auto& asset : app.assetCatalog.entries) {
        if (lowerText(asset.game) == lowerText(gameName)) {
            auto current = asset.path.parent_path();
            while (!current.empty() && current.has_parent_path()) {
                const auto name = lowerText(current.filename().string());
                if (name == lowerText(gameName) || name == "exported_files") {
                    if (name == "exported_files") return current / gameName;
                    return current;
                }
                if (name == "models" || name == "xmodels") {
                    return current.parent_path();
                }
                current = current.parent_path();
            }
            return asset.path.parent_path().parent_path();
        }
    }
    if (!app.defaultSalukiDirectory.empty()) {
        const auto candidate = app.defaultSalukiDirectory / "exported_files" / gameName;
        if (std::filesystem::is_directory(candidate)) return candidate;
        const auto candidate2 = app.defaultSalukiDirectory / gameName;
        if (std::filesystem::is_directory(candidate2)) return candidate2;
    }
    return {};
}

std::vector<std::filesystem::path> animationFoldersForGameRoot(const std::filesystem::path& gameRoot) {
    std::vector<std::filesystem::path> results;
    std::error_code ec;
    if (!std::filesystem::is_directory(gameRoot, ec)) return results;

    const auto animDirect = gameRoot / "_anims";
    if (std::filesystem::is_directory(animDirect, ec)) results.push_back(animDirect);
    const auto animDirect2 = gameRoot / "animations";
    if (std::filesystem::is_directory(animDirect2, ec)) results.push_back(animDirect2);
    const auto animDirect3 = gameRoot / "anims";
    if (std::filesystem::is_directory(animDirect3, ec)) results.push_back(animDirect3);
    const auto animDirect4 = gameRoot / "animtrees";
    if (std::filesystem::is_directory(animDirect4, ec)) results.push_back(animDirect4);

    if (results.empty()) {
        for (std::filesystem::recursive_directory_iterator it(gameRoot, std::filesystem::directory_options::skip_permission_denied, ec), end; it != end; it.increment(ec)) {
            if (ec) { ec.clear(); continue; }
            if (it->is_directory(ec)) {
                const auto name = lowerText(it->path().filename().string());
                if (name == "animations" || name == "_anims" || name == "anims" || name == "animtrees") {
                    results.push_back(it->path());
                    it.disable_recursion_pending();
                }
            }
        }
    }
    if (results.empty()) {
        results.push_back(gameRoot);
    }
    return results;
}

void loadEntireGameDirectory(AppState& app, const std::filesystem::path& gameRoot, std::string gameName) {
    if (gameName.empty()) {
        gameName = gameRoot.filename().string();
        if (lowerText(gameName) == "models" || lowerText(gameName) == "xmodels" || lowerText(gameName) == "animations") {
            gameName = gameRoot.parent_path().filename().string();
        }
    }
    const auto nameLow = lowerText(gameName);
    if (nameLow == "exported_files" || nameLow == "saluki" || nameLow == "greyhound") {
        std::error_code ec;
        for (std::filesystem::directory_iterator it(gameRoot, ec), end; it != end; it.increment(ec)) {
            if (ec) { ec.clear(); continue; }
            if (it->is_directory(ec)) {
                const auto subGame = it->path().filename().string();
                loadEntireGameDirectory(app, it->path(), subGame);
            }
        }
        return;
    }
    std::string err;
    (void)assets::appendScan(gameRoot, gameName, app.assetCatalog, err);

    const auto animFolders = animationFoldersForGameRoot(gameRoot);
    if (!animFolders.empty()) {
        queueAnimationFolders(app, animFolders);
    }

    mountGenericDualRig(app, gameName);
    app.classifierGameFilter = gameName;
    app.status = "Loaded full game assets and queued animations for [" + gameName + "]";
}

void ensureReferenceRigForClip(AppState& app, const scene::Animation& clip) {
    if (!app.classifierAutoSwitchRig) return;
    std::string game = clip.sourceGame;
    if (game.empty()) game = app.classifierGameFilter;
    if (game.empty() && !rippedGames(app).empty()) game = rippedGames(app).front();
    if (game.empty()) return;

    if (app.activeReferenceMode == AppState::ReferenceRigMode::Dual) return;

    const bool isViewmodel = (clip.domain == scene::AnimationDomain::ViewModel) ||
                             (clip.action == scene::ActionRole::Aim) ||
                             (clip.action == scene::ActionRole::Fire && !clip.name.starts_with("mp_") && !clip.name.starts_with("pb_")) ||
                             (clip.action == scene::ActionRole::Reload && !clip.name.starts_with("mp_") && !clip.name.starts_with("pb_")) ||
                             (clip.ads);

    if (isViewmodel) {
        if (app.activeReferenceMode != AppState::ReferenceRigMode::Viewmodel || app.selectedBaseAsset >= app.assetCatalog.entries.size()) {
            mountGenericViewmodel(app, game);
        }
    } else {
        if (app.activeReferenceMode != AppState::ReferenceRigMode::Playermodel) {
            mountGenericPlayermodel(app, game);
        }
    }
}

void drawBotDecisionMatrix(AppState& app) {
    if (!ImGui::CollapsingHeader("Game Bot Play Area Decisions (Locomotion Sets & Directional Deaths)", ImGuiTreeNodeFlags_None)) {
        return;
    }

    uiHelp("Select a game to inspect, live-preview, and freely swap out bot locomotion choices and in-use directional death animations.");

    // --- Game Dropdown ---
    const auto games = rippedGames(app);
    if (games.empty()) {
        ImGui::TextDisabled("No ripped games detected in the asset catalog. Load a game rip folder above.");
        return;
    }

    if (app.classifierDecisionGame.empty() || std::find(games.begin(), games.end(), app.classifierDecisionGame) == games.end()) {
        app.classifierDecisionGame = !app.classifierGameFilter.empty() ? app.classifierGameFilter : games.front();
    }

    int gameIdx = 0;
    for (std::size_t i = 0; i < games.size(); ++i) {
        if (lowerText(games[i]) == lowerText(app.classifierDecisionGame)) {
            gameIdx = static_cast<int>(i);
            break;
        }
    }

    ImGui::SetNextItemWidth(180.0f);
    if (ImGui::BeginCombo("Select Game##bot_decisions_game", games[gameIdx].c_str())) {
        for (int i = 0; i < static_cast<int>(games.size()); ++i) {
            const bool isSel = (i == gameIdx);
            if (ImGui::Selectable(games[i].c_str(), isSel)) {
                gameIdx = i;
                app.classifierDecisionGame = games[i];
            }
        }
        ImGui::EndCombo();
    }
    ImGui::SameLine();

    const std::string selectedGame = app.classifierDecisionGame;
    const std::string selGameLower = lowerText(selectedGame);

    if (ImGui::Button(("Mount Dual Rig [" + selectedGame + "]").c_str())) {
        mountGenericDualRig(app, selectedGame);
    }
    ImGui::SameLine();
    if (ImGui::Button(("Mount Playermodel [" + selectedGame + "]").c_str())) {
        mountGenericPlayermodel(app, selectedGame);
    }
    ImGui::SameLine();
    if (ImGui::Button("Load Full Game Directory##bot_decision_load")) {
        const auto root = gameRootDirectoryForGame(app, selectedGame);
        if (!root.empty()) {
            loadEntireGameDirectory(app, root, selectedGame);
        }
    }

    // Tally animation statistics for this game in the loaded scene
    std::size_t totalGameClips = 0;
    std::size_t locoCount = 0;
    std::size_t deathCount = 0;
    std::vector<std::size_t> gameDeathIndices;
    std::vector<std::size_t> gameLocoIndices;

    for (std::size_t i = 0; i < app.scene.animations.size(); ++i) {
        const auto& anim = app.scene.animations[i];
        const bool matchGame = (!anim.sourceGame.empty() && lowerText(anim.sourceGame) == selGameLower) ||
                               (anim.sourceGame.empty() && lowerText(app.classifierGameFilter) == selGameLower);
        if (!matchGame) continue;
        ++totalGameClips;

        const bool isHumanoid = (anim.domain == scene::AnimationDomain::PlayerBody || anim.domain == scene::AnimationDomain::PlayerTorso);
        if (anim.action == scene::ActionRole::Death || anim.name.find("death") != std::string::npos || anim.name.find("die") != std::string::npos) {
            if (isHumanoid) {
                ++deathCount;
                gameDeathIndices.push_back(i);
            }
        } else if (isHumanoid && anim.motion != scene::MotionRole::Unknown) {
            ++locoCount;
            gameLocoIndices.push_back(i);
        }
    }

    ImGui::TextColored(ImVec4(0.4f, 0.85f, 1.0f, 1.0f), "Game: %s | Total Loaded Clips: %zu | Locomotion Candidates: %zu | Directional Deaths: %zu",
                       selectedGame.c_str(), totalGameClips, locoCount, deathCount);

    if (totalGameClips == 0) {
        ImGui::TextColored(ImVec4(1.0f, 0.75f, 0.2f, 1.0f), "Note: No clips loaded for [%s] in current scene. Click 'Load Full Game Directory' above to populate.", selectedGame.c_str());
    }

    ImGui::Separator();

    // =========================================================================
    // SECTION 1: BOT LOCOMOTION CHOICES FOR SELECTED GAME
    // =========================================================================
    if (ImGui::TreeNodeEx("1. Bot Locomotion Choices (Decision Matrix & Swapping)", ImGuiTreeNodeFlags_None)) {
        uiHelp("Evaluates movement choices (Stance x Motion x Direction x Weapon) for [%s]. You can swap any clip with any other animation:", selectedGame.c_str());

        // Weapon filter for locomotion evaluation
        const char* wFilterNames[] = {"Rifle (Standard)", "Pistol", "Dual Wield", "Shotgun", "LMG", "Sniper", "Heavy / SAW", "Knife", "Any Weapon"};
        scene::WeaponClass wFilterValues[] = {
            scene::WeaponClass::Rifle, scene::WeaponClass::Pistol, scene::WeaponClass::DualWield,
            scene::WeaponClass::Shotgun, scene::WeaponClass::LMG, scene::WeaponClass::Sniper,
            scene::WeaponClass::Heavy, scene::WeaponClass::Knife, scene::WeaponClass::Any
        };

        ImGui::SetNextItemWidth(160.0f);
        ImGui::Combo("Weapon Class##bot_loco_w", &app.classifierDecisionLocoWeapon, wFilterNames, 9);
        const scene::WeaponClass selectedWpn = wFilterValues[std::clamp(app.classifierDecisionLocoWeapon, 0, 8)];

        ImGui::SameLine();
        const char* sFilterNames[] = {"All Stances", "Stand Only", "Crouch Only", "Prone Only"};
        ImGui::SetNextItemWidth(130.0f);
        ImGui::Combo("Stance Filter##bot_loco_s", &app.classifierDecisionLocoStance, sFilterNames, 4);
        ImGui::SameLine();

        if (ImGui::SmallButton("Reset All Locomotion Overrides for Game")) {
            ++app.botLocomotionOverrideRevision;
            for (auto it = app.botLocomotionOverrides.begin(); it != app.botLocomotionOverrides.end(); ) {
                if (it->first.game == selectedGame) it = app.botLocomotionOverrides.erase(it);
                else ++it;
            }
            app.status = "Reset all locomotion animation overrides for [" + selectedGame + "]";
        }

        struct LocoCategory {
            const char* label;
            scene::MotionRole motion;
            scene::Stance stance;
            scene::Direction direction;
            const char* description;
        };

        const std::vector<LocoCategory> categories = {
            // Stand Locomotion
            {"Stand Run [Forward]", scene::MotionRole::Run, scene::Stance::Stand, scene::Direction::Forward, "Primary forward movement when engaging or pursuing"},
            {"Stand Run [Backward]", scene::MotionRole::Run, scene::Stance::Stand, scene::Direction::Backward, "Backpedal / retreat while maintaining facing"},
            {"Stand Run [Left]", scene::MotionRole::Run, scene::Stance::Stand, scene::Direction::Left, "Left tactical combat strafe"},
            {"Stand Run [Right]", scene::MotionRole::Run, scene::Stance::Stand, scene::Direction::Right, "Right tactical combat strafe"},
            {"Stand Sprint", scene::MotionRole::Sprint, scene::Stance::Stand, scene::Direction::Forward, "Fast sprint intent during long distance traversal"},
            {"Stand Walk [Forward]", scene::MotionRole::Walk, scene::Stance::Stand, scene::Direction::Forward, "Slow scan / patrol walk forward"},
            {"Stand Walk [Backward]", scene::MotionRole::Walk, scene::Stance::Stand, scene::Direction::Backward, "Careful backward step"},
            {"Stand Walk [Left]", scene::MotionRole::Walk, scene::Stance::Stand, scene::Direction::Left, "Slow left strafe walk"},
            {"Stand Walk [Right]", scene::MotionRole::Walk, scene::Stance::Stand, scene::Direction::Right, "Slow right strafe walk"},
            {"Stand Idle", scene::MotionRole::Idle, scene::Stance::Stand, scene::Direction::Any, "Static upright idle / guard posture"},

            // Crouch Locomotion
            {"Crouch Walk [Forward]", scene::MotionRole::Walk, scene::Stance::Crouch, scene::Direction::Forward, "Low-profile forward advance"},
            {"Crouch Walk [Backward]", scene::MotionRole::Walk, scene::Stance::Crouch, scene::Direction::Backward, "Low-profile backward step"},
            {"Crouch Walk [Left]", scene::MotionRole::Walk, scene::Stance::Crouch, scene::Direction::Left, "Low-profile left strafe"},
            {"Crouch Walk [Right]", scene::MotionRole::Walk, scene::Stance::Crouch, scene::Direction::Right, "Low-profile right strafe"},
            {"Crouch Idle", scene::MotionRole::Idle, scene::Stance::Crouch, scene::Direction::Any, "Stationary crouch cover pose"},

            // Prone Locomotion
            {"Prone Crawl [Forward]", scene::MotionRole::Crawl, scene::Stance::Prone, scene::Direction::Forward, "Prone stomach crawl forward"},
            {"Prone Crawl [Backward]", scene::MotionRole::Crawl, scene::Stance::Prone, scene::Direction::Backward, "Prone stomach crawl backward"},
            {"Prone Crawl [Left]", scene::MotionRole::Crawl, scene::Stance::Prone, scene::Direction::Left, "Prone stomach crawl left"},
            {"Prone Crawl [Right]", scene::MotionRole::Crawl, scene::Stance::Prone, scene::Direction::Right, "Prone stomach crawl right"},
            {"Prone Idle", scene::MotionRole::Idle, scene::Stance::Prone, scene::Direction::Any, "Stationary prone ground pose"},

            // Airborne & Traversal
            {"Jump [Takeoff / Airborne]", scene::MotionRole::Jump, scene::Stance::Stand, scene::Direction::Any, "Jump takeoff / airborne apex"},
            {"Jump [Landing]", scene::MotionRole::Land, scene::Stance::Stand, scene::Direction::Any, "Touchdown impact landing"},
            {"Mantle / Climb", scene::MotionRole::Climb, scene::Stance::Stand, scene::Direction::Any, "Obstacle vault / ledge mantle"},
            {"Slide / Dive", scene::MotionRole::Slide, scene::Stance::Crouch, scene::Direction::Any, "Tactical slide or dolphin dive"}
        };

        ImGui::SetNextItemWidth(260.0f);
        ImGui::InputTextWithHint("##loco_swap_search", "Search / filter swap animations...", app.locoSwapFilter.data(), app.locoSwapFilter.size());
        ImGui::SameLine();
        if (ImGui::SmallButton("Clear Search##loco")) app.locoSwapFilter.fill('\0');

        if (ImGui::BeginTable("bot_loco_decision_table", 5, ImGuiTableFlags_Borders | ImGuiTableFlags_RowBg | ImGuiTableFlags_Resizable)) {
            ImGui::TableSetupColumn("Locomotion Role", ImGuiTableColumnFlags_WidthFixed, 180.0f);
            ImGui::TableSetupColumn("Active Pick & Status", ImGuiTableColumnFlags_WidthFixed, 320.0f);
            ImGui::TableSetupColumn("Swap / Override Clip", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableSetupColumn("Speed (u/s)", ImGuiTableColumnFlags_WidthFixed, 75.0f);
            ImGui::TableSetupColumn("Preview", ImGuiTableColumnFlags_WidthFixed, 65.0f);
            ImGui::TableHeadersRow();

            for (std::size_t cIdx = 0; cIdx < categories.size(); ++cIdx) {
                const auto& cat = categories[cIdx];
                if (app.classifierDecisionLocoStance == 1 && cat.stance != scene::Stance::Stand) continue;
                if (app.classifierDecisionLocoStance == 2 && cat.stance != scene::Stance::Crouch) continue;
                if (app.classifierDecisionLocoStance == 3 && cat.stance != scene::Stance::Prone) continue;

                scene::AnimationQuery query;
                query.domain = scene::AnimationDomain::PlayerBody;
                query.motion = cat.motion;
                query.stance = cat.stance;
                query.direction = cat.direction;
                query.weapon = selectedWpn;

                AppState::BotLocomotionOverrideKey overrideKey{selectedGame, cat.motion, cat.stance, cat.direction, selectedWpn};
                const auto oIt = app.botLocomotionOverrides.find(overrideKey);
                const bool hasOverride = (oIt != app.botLocomotionOverrides.end());

                const auto resolvedIdx = botLocomotionAnimation(app.scene, query, &app);

                ImGui::TableNextRow();
                ImGui::TableSetColumnIndex(0);
                ImGui::TextColored(ImVec4(0.9f, 0.9f, 0.9f, 1.0f), "%s", cat.label);
                ImGui::TextDisabled("%s", cat.description);

                ImGui::TableSetColumnIndex(1);
                if (hasOverride) {
                    ImGui::TextColored(ImVec4(0.2f, 0.9f, 1.0f, 1.0f), "[Custom]: %s", oIt->second.c_str());
                    if (ImGui::IsItemHovered()) {
                        uiHelp("Custom Override: %s\nGame: %s\nRole: %s", oIt->second.c_str(), selectedGame.c_str(), cat.label);
                    }
                    ImGui::PushID(static_cast<int>(cIdx) + 60000);
                    if (ImGui::SmallButton("Reset to Auto")) {
                        app.botLocomotionOverrides.erase(oIt); ++app.botLocomotionOverrideRevision;
                    }
                    ImGui::PopID();
                } else if (resolvedIdx && *resolvedIdx < app.scene.animations.size()) {
                    const auto& pick = app.scene.animations[*resolvedIdx];
                    ImGui::TextColored(ImVec4(0.3f, 0.9f, 0.4f, 1.0f), "[Auto]: %s", pick.name.c_str());
                    if (ImGui::IsItemHovered()) {
                        uiHelp("Raw Name: %s\nSource: %s\nGame: %s\nWeapon: %s\nStance: %s\nDirection: %s\nTracks: %zu\nFrames: %u (%.2fs)",
                                          pick.name.c_str(), pick.sourceName.c_str(), pick.sourceGame.c_str(),
                                          scene::weaponClassName(pick.weapon), scene::stanceName(pick.stance), scene::directionName(pick.direction),
                                          pick.tracks.size(), pick.durationFrames, static_cast<float>(pick.durationFrames) / std::max(1.0f, pick.framerate));
                    }
                    if (!pick.sourceName.empty() && pick.sourceName != pick.name) {
                        ImGui::TextDisabled("Src: %s | %s", pick.sourceName.c_str(), scene::weaponClassName(pick.weapon));
                    } else {
                        ImGui::TextDisabled("Weapon: %s | %u fr", scene::weaponClassName(pick.weapon), pick.durationFrames);
                    }
                } else {
                    ImGui::TextColored(ImVec4(0.9f, 0.6f, 0.2f, 1.0f), "No direct match (Fallback)");
                }

                ImGui::TableSetColumnIndex(2);
                ImGui::PushID(static_cast<int>(cIdx) + 65000);
                const std::string comboLabel = hasOverride ? oIt->second : ((resolvedIdx && *resolvedIdx < app.scene.animations.size()) ? app.scene.animations[*resolvedIdx].name : "Choose Swap...");
                if (ImGui::BeginCombo("##swap_loco", comboLabel.c_str())) {
                    static char inlineLocoSearch[64] = "";
                    ImGui::SetNextItemWidth(-1.0f);
                    ImGui::InputTextWithHint("##inline_loco_search", "Search anims in library...", inlineLocoSearch, sizeof(inlineLocoSearch));
                    if (ImGui::Selectable("<Reset to Auto-Detection>", !hasOverride)) {
                        if (hasOverride) {app.botLocomotionOverrides.erase(overrideKey); ++app.botLocomotionOverrideRevision;}
                    }
                    ImGui::Separator();

                    const std::string inlineStr = lowerText(inlineLocoSearch);
                    const std::string locoSearch = !inlineStr.empty() ? inlineStr : lowerText(app.locoSwapFilter.data());

                    // 1. Relevant game locomotion clips
                    ImGui::TextDisabled("--- Game Locomotion Matches ---");
                    for (std::size_t idx : gameLocoIndices) {
                        const auto& cand = app.scene.animations[idx];
                        if (!locoSearch.empty() && lowerText(cand.name).find(locoSearch) == std::string::npos && lowerText(cand.sourceName).find(locoSearch) == std::string::npos) continue;
                        const bool isCur = (hasOverride && oIt->second == cand.name) || (!hasOverride && resolvedIdx && *resolvedIdx == idx);
                        const std::string itemLabel = cand.name + " (" + scene::weaponClassName(cand.weapon) + ")" + (cand.sourceName.empty() || cand.sourceName == cand.name ? "" : " [" + cand.sourceName + "]");
                        if (ImGui::Selectable((itemLabel + "##cand_" + std::to_string(idx)).c_str(), isCur)) {
                            app.botLocomotionOverrides[overrideKey] = cand.name; ++app.botLocomotionOverrideRevision;
                            ensurePlayermodelMounted(app, selectedGame);
                            app.animationIndex = app.previousAnimationIndex = idx;
                            app.animationFrame = 0;
                            app.playing = true;
                            app.classifierSelectedClip = static_cast<int>(idx);
                        }
                        if (ImGui::IsItemHovered()) {
                            uiHelp("Raw Name: %s\nSource: %s\nWeapon: %s | Stance: %s | Dir: %s\nTracks: %zu | Frames: %u",
                                              cand.name.c_str(), cand.sourceName.c_str(), scene::weaponClassName(cand.weapon),
                                              scene::stanceName(cand.stance), scene::directionName(cand.direction),
                                              cand.tracks.size(), cand.durationFrames);
                        }
                    }

                    // 2. All other clips in scene
                    ImGui::Separator();
                    ImGui::TextDisabled("--- All Loaded Scene Clips ---");
                    for (std::size_t idx = 0; idx < app.scene.animations.size(); ++idx) {
                        const auto& cand = app.scene.animations[idx];
                        if (!locoSearch.empty() && lowerText(cand.name).find(locoSearch) == std::string::npos && lowerText(cand.sourceName).find(locoSearch) == std::string::npos) continue;
                        const bool isCur = (hasOverride && oIt->second == cand.name) || (!hasOverride && resolvedIdx && *resolvedIdx == idx);
                        const std::string candDisplay = (!cand.sourceName.empty() && (cand.name == "anim" || cand.name.starts_with("animation_")))
                            ? std::filesystem::path(cand.sourceName).filename().string()
                            : (!cand.sourceName.empty() && cand.sourceName != cand.name
                                ? (cand.name + " [" + std::filesystem::path(cand.sourceName).filename().string() + "]")
                                : cand.name);
                        const std::string itemLabel = candDisplay + " [" + (cand.sourceGame.empty() ? "Generic" : cand.sourceGame) + "] (" + scene::weaponClassName(cand.weapon) + ")";
                        if (ImGui::Selectable((itemLabel + "##all_" + std::to_string(idx)).c_str(), isCur)) {
                            app.botLocomotionOverrides[overrideKey] = cand.name; ++app.botLocomotionOverrideRevision;
                            saveBotOverrides(app);
                            ensurePlayermodelMounted(app, selectedGame);
                            app.animationIndex = app.previousAnimationIndex = idx;
                            app.animationFrame = 0;
                            app.playing = true;
                            app.classifierSelectedClip = static_cast<int>(idx);
                        }
                        if (ImGui::IsItemHovered()) {
                            uiHelp("Raw Name: %s\nSource: %s\nGame: %s\nDomain: %s | Weapon: %s\nTracks: %zu | Frames: %u",
                                              cand.name.c_str(), cand.sourceName.c_str(), cand.sourceGame.c_str(),
                                              scene::animationDomainName(cand.domain), scene::weaponClassName(cand.weapon),
                                              cand.tracks.size(), cand.durationFrames);
                        }
                    }
                    ImGui::EndCombo();
                }
                ImGui::PopID();

                ImGui::TableSetColumnIndex(3);
                if (resolvedIdx && *resolvedIdx < app.botClipAuthoredSpeeds.size()) {
                    const float spd = app.botClipAuthoredSpeeds[*resolvedIdx];
                    if (spd > 0.01f) {
                        ImGui::Text("%.1f", spd);
                    } else {
                        ImGui::TextDisabled("-");
                    }
                } else {
                    ImGui::TextDisabled("-");
                }

                ImGui::TableSetColumnIndex(4);
                if (resolvedIdx && *resolvedIdx < app.scene.animations.size()) {
                    ImGui::PushID(static_cast<int>(*resolvedIdx) + 80000);
                    if (ImGui::SmallButton("Play")) {
                        ensurePlayermodelMounted(app, selectedGame);
                        app.animationIndex = app.previousAnimationIndex = *resolvedIdx;
                        app.animationFrame = 0;
                        app.playing = true;
                        app.classifierSelectedClip = static_cast<int>(*resolvedIdx);
                    }
                    ImGui::PopID();
                }
            }
            ImGui::EndTable();
        }
        ImGui::TreePop();
    }

    ImGui::Separator();

    // =========================================================================
    // SECTION 2: IN-USE DIRECTIONAL BOT DEATH ANIMATIONS
    // =========================================================================
    if (ImGui::TreeNodeEx("2. In-Use Directional Bot Death Animations (Inspection & Swapping)", ImGuiTreeNodeFlags_None)) {
        ImGui::TextDisabled("All directional and situational death clips for [%s]. You can preview, remove, or swap in custom death clips per direction:", selectedGame.c_str());

        const char* dirFilterNames[] = {"All Directions", "Forward Deaths (Front Hit)", "Backward Deaths (Back Hit)", "Left Flank Deaths", "Right Flank Deaths", "Omni / General Deaths"};
        ImGui::SetNextItemWidth(200.0f);
        ImGui::Combo("Direction Filter##bot_death_dir", &app.classifierDecisionDeathDirection, dirFilterNames, 6);
        ImGui::SameLine();

        if (ImGui::SmallButton("Reset All Death Overrides for Game")) {
            for (auto it = app.botDeathOverrides.begin(); it != app.botDeathOverrides.end(); ) {
                if (it->first.first == selectedGame) it = app.botDeathOverrides.erase(it);
                else ++it;
            }
            saveBotOverrides(app);
            app.status = "Reset all death animation overrides for [" + selectedGame + "]";
        }

        struct DeathGroup {
            const char* header;
            scene::Direction direction;
            const char* desc;
        };

        const std::vector<DeathGroup> groups = {
            {"Frontal Impact Deaths [Shot from Front -> Falls Backward / Forward]", scene::Direction::Forward, "Triggered when lethal damage arrives from actor's front vision arc"},
            {"Rear Impact Deaths [Shot from Behind -> Falls Forward]", scene::Direction::Backward, "Triggered when lethal damage hits from behind / back arc"},
            {"Left Flank Deaths [Shot from Left -> Falls Right]", scene::Direction::Left, "Triggered when actor takes lethal fire from the left flank"},
            {"Right Flank Deaths [Shot from Right -> Falls Left]", scene::Direction::Right, "Triggered when actor takes lethal fire from the right flank"},
            {"General & Specialty Deaths [Running / Crouch / Prone / Headshot / Chest Spin]", scene::Direction::Any, "Omni-directional, running transitions, stance-specific, and hit-location deaths"}
        };

        ImGui::SetNextItemWidth(260.0f);
        ImGui::InputTextWithHint("##death_swap_search", "Search / filter death animations...", app.deathSwapFilter.data(), app.deathSwapFilter.size());
        ImGui::SameLine();
        if (ImGui::SmallButton("Clear Search##death")) app.deathSwapFilter.fill('\0');

        for (std::size_t gIdx = 0; gIdx < groups.size(); ++gIdx) {
            const auto& grp = groups[gIdx];
            if (app.classifierDecisionDeathDirection == 1 && grp.direction != scene::Direction::Forward) continue;
            if (app.classifierDecisionDeathDirection == 2 && grp.direction != scene::Direction::Backward) continue;
            if (app.classifierDecisionDeathDirection == 3 && grp.direction != scene::Direction::Left) continue;
            if (app.classifierDecisionDeathDirection == 4 && grp.direction != scene::Direction::Right) continue;
            if (app.classifierDecisionDeathDirection == 5 && grp.direction != scene::Direction::Any) continue;

            const bool isOpen = ImGui::TreeNodeEx((std::string(grp.header) + "##grp_" + std::to_string(gIdx)).c_str(), ImGuiTreeNodeFlags_DefaultOpen);
            if (!isOpen) continue;

            ImGui::TextDisabled("%s", grp.desc);

            std::vector<std::size_t> groupClips;
            const auto dOverrideKey = std::make_pair(selectedGame, grp.direction);
            const auto dIt = app.botDeathOverrides.find(dOverrideKey);
            const bool hasCustomDeaths = (dIt != app.botDeathOverrides.end() && !dIt->second.empty());

            if (hasCustomDeaths) {
                for (const auto& customName : dIt->second) {
                    for (std::size_t i = 0; i < app.scene.animations.size(); ++i) {
                        if (app.scene.animations[i].name == customName) {
                            groupClips.push_back(i);
                            break;
                        }
                    }
                }
            } else {
                for (std::size_t i = 0; i < app.scene.animations.size(); ++i) {
                    const auto& anim = app.scene.animations[i];
                    if (anim.action != scene::ActionRole::Death || anim.tracks.empty() ||
                        (anim.domain != scene::AnimationDomain::PlayerBody && anim.domain != scene::AnimationDomain::PlayerTorso)) continue;
                    if (!anim.sourceGame.empty() && lowerText(anim.sourceGame) != lowerText(selectedGame)) continue;
                    if (grp.direction != scene::Direction::Any && anim.direction != grp.direction && anim.direction != scene::Direction::Any) continue;
                    groupClips.push_back(i);
                }
            }

            ImGui::PushID(static_cast<int>(gIdx) + 90000);
            if (ImGui::BeginCombo("##add_death_clip", "+ Add Death Clip to Group...")) {
                static char inlineDeathSearch[64] = "";
                ImGui::SetNextItemWidth(-1.0f);
                ImGui::InputTextWithHint("##inline_death_search", "Search anims in library...", inlineDeathSearch, sizeof(inlineDeathSearch));
                ImGui::Separator();

                const std::string inlineDStr = lowerText(inlineDeathSearch);
                const std::string deathSearch = !inlineDStr.empty() ? inlineDStr : lowerText(app.deathSwapFilter.data());

                ImGui::TextDisabled("--- Game Directional Death Clips ---");
                for (std::size_t idx = 0; idx < app.scene.animations.size(); ++idx) {
                    const auto& anim = app.scene.animations[idx];
                    if (anim.action != scene::ActionRole::Death || anim.tracks.empty() ||
                        (anim.domain != scene::AnimationDomain::PlayerBody && anim.domain != scene::AnimationDomain::PlayerTorso)) continue;
                    if (!anim.sourceGame.empty() && lowerText(anim.sourceGame) != lowerText(selectedGame)) continue;
                    if (!deathSearch.empty() && lowerText(anim.name).find(deathSearch) == std::string::npos && lowerText(anim.sourceName).find(deathSearch) == std::string::npos) continue;

                    const std::string dLabel = anim.name + " (" + scene::directionName(anim.direction) + ", " + scene::weaponClassName(anim.weapon) + ")";
                    if (ImGui::Selectable((dLabel + "##pickdeath_" + std::to_string(idx)).c_str())) {
                        auto& dList = app.botDeathOverrides[dOverrideKey];
                        if (dList.empty()) {
                            for (std::size_t cIdx : groupClips) dList.push_back(app.scene.animations[cIdx].name);
                        }
                        if (std::find(dList.begin(), dList.end(), anim.name) == dList.end()) {
                            dList.push_back(anim.name);
                        }
                        saveBotOverrides(app);
                        ensurePlayermodelMounted(app, selectedGame);
                        app.animationIndex = app.previousAnimationIndex = idx;
                        app.animationFrame = 0;
                        app.playing = true;
                        app.classifierSelectedClip = static_cast<int>(idx);
                    }
                }
                ImGui::Separator();
                ImGui::TextDisabled("--- All Loaded Scene Clips ---");
                for (std::size_t idx = 0; idx < app.scene.animations.size(); ++idx) {
                    const auto& anim = app.scene.animations[idx];
                    if (!deathSearch.empty() && lowerText(anim.name).find(deathSearch) == std::string::npos && lowerText(anim.sourceName).find(deathSearch) == std::string::npos) continue;
                    const std::string animDisplay = (!anim.sourceName.empty() && (anim.name == "anim" || anim.name.starts_with("animation_")))
                        ? std::filesystem::path(anim.sourceName).filename().string()
                        : (!anim.sourceName.empty() && anim.sourceName != anim.name
                            ? (anim.name + " [" + std::filesystem::path(anim.sourceName).filename().string() + "]")
                            : anim.name);
                    const std::string dLabel = animDisplay + " [" + (anim.sourceGame.empty() ? "Generic" : anim.sourceGame) + "] (" + scene::directionName(anim.direction) + ")";
                    if (ImGui::Selectable((dLabel + "##alldeath_" + std::to_string(idx)).c_str())) {
                        auto& dList = app.botDeathOverrides[dOverrideKey];
                        if (std::find(dList.begin(), dList.end(), anim.name) == dList.end()) {
                            dList.push_back(anim.name);
                        }
                        saveBotOverrides(app);
                        ensurePlayermodelMounted(app, selectedGame);
                        app.animationIndex = app.previousAnimationIndex = idx;
                        app.animationFrame = 0;
                        app.playing = true;
                        app.classifierSelectedClip = static_cast<int>(idx);
                    }
                }
                ImGui::EndCombo();
            }
            ImGui::SameLine();
            if (hasCustomDeaths) {
                if (ImGui::SmallButton("Reset Direction to Auto")) {
                    app.botDeathOverrides.erase(dOverrideKey);
                    saveBotOverrides(app);
                }
            }

            if (groupClips.empty()) {
                ImGui::TextDisabled("No specific clips active for this directional category in [%s].", selectedGame.c_str());
            } else {
                if (ImGui::BeginTable("death_group_table", 8, ImGuiTableFlags_Borders | ImGuiTableFlags_RowBg | ImGuiTableFlags_Resizable)) {
                    ImGui::TableSetupColumn("Action", ImGuiTableColumnFlags_WidthFixed, 65.0f);
                    ImGui::TableSetupColumn("Animation Name (Raw)", ImGuiTableColumnFlags_WidthStretch);
                    ImGui::TableSetupColumn("Stance", ImGuiTableColumnFlags_WidthFixed, 60.0f);
                    ImGui::TableSetupColumn("Motion", ImGuiTableColumnFlags_WidthFixed, 65.0f);
                    ImGui::TableSetupColumn("Weapon", ImGuiTableColumnFlags_WidthFixed, 75.0f);
                    ImGui::TableSetupColumn("Frames", ImGuiTableColumnFlags_WidthFixed, 50.0f);
                    ImGui::TableSetupColumn("Duration", ImGuiTableColumnFlags_WidthFixed, 60.0f);
                    ImGui::TableSetupColumn("Remove", ImGuiTableColumnFlags_WidthFixed, 55.0f);
                    ImGui::TableHeadersRow();

                    for (std::size_t i = 0; i < groupClips.size(); ++i) {
                        const std::size_t idx = groupClips[i];
                        const auto& anim = app.scene.animations[idx];
                        ImGui::TableNextRow();

                        ImGui::TableSetColumnIndex(0);
                        ImGui::PushID(static_cast<int>(idx) + 95000);
                        if (ImGui::SmallButton("Preview")) {
                            ensurePlayermodelMounted(app, selectedGame);
                            app.animationIndex = app.previousAnimationIndex = idx;
                            app.animationFrame = 0;
                            app.playing = true;
                            app.classifierSelectedClip = static_cast<int>(idx);
                        }
                        if (ImGui::IsItemHovered()) {
                            uiHelp("Raw Name: %s\nSource: %s\nGame: %s\nWeapon: %s | Stance: %s | Dir: %s\nTracks: %zu | Frames: %u (%.2fs)",
                                              anim.name.c_str(), anim.sourceName.c_str(), anim.sourceGame.c_str(),
                                              scene::weaponClassName(anim.weapon), scene::stanceName(anim.stance), scene::directionName(anim.direction),
                                              anim.tracks.size(), anim.durationFrames, static_cast<float>(anim.durationFrames) / std::max(1.0f, anim.framerate));
                        }
                        if (!anim.sourceName.empty() && anim.sourceName != anim.name) {
                            ImGui::TextDisabled("Src: %s", anim.sourceName.c_str());
                        }

                        ImGui::TableSetColumnIndex(2);
                        ImGui::Text("%s", scene::stanceName(anim.stance));

                        ImGui::TableSetColumnIndex(3);
                        ImGui::Text("%s", scene::motionRoleName(anim.motion));

                        ImGui::TableSetColumnIndex(4);
                        ImGui::Text("%s", scene::weaponClassName(anim.weapon));

                        ImGui::TableSetColumnIndex(5);
                        ImGui::Text("%u", anim.durationFrames);

                        ImGui::TableSetColumnIndex(6);
                        const float durSec = static_cast<float>(anim.durationFrames) / std::max(1.0f, anim.framerate);
                        ImGui::Text("%.2fs", durSec);

                        ImGui::TableSetColumnIndex(7);
                        ImGui::PushID(static_cast<int>(idx) + 98000);
                        if (ImGui::SmallButton("X##rem_death")) {
                            auto& dList = app.botDeathOverrides[dOverrideKey];
                            if (dList.empty()) {
                                for (std::size_t cIdx : groupClips) {
                                    if (cIdx != idx) dList.push_back(app.scene.animations[cIdx].name);
                                }
                            } else {
                                dList.erase(std::remove(dList.begin(), dList.end(), anim.name), dList.end());
                            }
                            saveBotOverrides(app);
                        }
                        ImGui::PopID();
                    }
                    ImGui::EndTable();
                }
            }
            ImGui::TreePop();
        }
        ImGui::PopID();
    }
    ImGui::TreePop();
}

bool gameHasModularParts(const AppState& app, const std::string& activeGame){
    if(activeGame.empty()) return false;
    const auto gLower = lowerText(activeGame);
    for(const auto& a : app.assetCatalog.entries){
        if(lowerText(a.game) != gLower) continue;
        const auto cname = lowerText(a.name);
        if(cname.starts_with("mp_helmet") || cname.starts_with("mp_eyewear") || cname.starts_with("mp_glove") ||
           cname.starts_with("mp_pants") || cname.starts_with("mp_kneepad") || cname.starts_with("mp_boot") ||
           cname.starts_with("mp_exo") || cname.starts_with("mp_gear") || cname.starts_with("mp_vest") ||
           cname.starts_with("mp_hat") || cname.find("fso_vest") != std::string::npos) {
            return true;
        }
    }
    return false;
}

bool drawModularPartsCustomization(AppState& app, const std::string& activeGame){
    if(!gameHasModularParts(app, activeGame)) return false;
    bool changed=false;
    auto& setup = app.gameReferenceSetups[activeGame];
    const auto gLower = lowerText(activeGame);

    const auto drawPartCombo = [&](const char* label, std::size_t& targetSlot, const std::vector<std::string>& searchTokens){
        const std::string curName = (targetSlot < app.assetCatalog.entries.size()) ? app.assetCatalog.entries[targetSlot].name : "<None / Default>";
        if(ImGui::BeginCombo(label, curName.c_str())){
            if(ImGui::Selectable("<None / Default>", targetSlot >= app.assetCatalog.entries.size())){
                targetSlot = static_cast<std::size_t>(-1);
                changed=true;
            }
            for(std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i){
                const auto& a = app.assetCatalog.entries[i];
                if(!activeGame.empty() && lowerText(a.game) != gLower) continue;
                const auto cname = lowerText(a.name);
                bool matches = false;
                for(const auto& tok : searchTokens){
                    if(cname.find(tok) != std::string::npos){ matches = true; break; }
                }
                if(!matches||!assets::character::matchesSlot(activeGame,a.name,label)) continue;
                if(ImGui::Selectable(a.name.c_str(), targetSlot == i)){
                    targetSlot = i;
                    changed=true;
                }
            }
            ImGui::EndCombo();
        }
    };

    drawPartCombo("Helmet / Hat", setup.helmetAsset, {"helmet", "hat", "cap", "beret", "mp_helmet", "headgear"});
    drawPartCombo("Eyewear / Visor", setup.eyewearAsset, {"eyewear", "glasses", "goggles", "visor", "mp_eyewear"});
    drawPartCombo("Gloves / Hands", setup.glovesAsset, {"glove", "gloves", "hands", "mp_glove"});
    drawPartCombo("Pants / Legs", setup.pantsAsset, {"pants", "legs", "trousers", "mp_pants", "mp_legs"});
    drawPartCombo("Kneepads", setup.kneepadAsset, {"kneepad", "kneepads", "mp_kneepad"});
    drawPartCombo("Boots / Shoes", setup.bootsAsset, {"boot", "boots", "shoes", "mp_boot"});
    drawPartCombo("Exo", setup.exoAsset, {"exo"});
    drawPartCombo("Loadout / Gear", setup.loadoutAsset, {"loadout", "gear"});
    drawPartCombo("Shinguards", setup.shinguardAsset, {"shinguard"});

    // Extra custom modular part adder
    static char customPartSearch[64] = "";
    ImGui::InputTextWithHint("##custom_part_filter", "Filter extra modular parts...", customPartSearch, sizeof(customPartSearch));
    const std::string extraQuery = lowerText(customPartSearch);
    if(ImGui::BeginCombo("Add Extra Modular Part", "Select model from library...")){
        for(std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i){
            const auto& a = app.assetCatalog.entries[i];
            if(!activeGame.empty() && lowerText(a.game) != gLower) continue;
            if(!extraQuery.empty() && lowerText(a.name).find(extraQuery) == std::string::npos) continue;
            if(ImGui::Selectable(a.name.c_str(), false)){
                if(std::find(setup.customModularParts.begin(), setup.customModularParts.end(), i) == setup.customModularParts.end()){
                    setup.customModularParts.push_back(i);
                    changed=true;
                }
            }
        }
        ImGui::EndCombo();
    }
    if(!setup.customModularParts.empty()){
        ImGui::TextDisabled("Equipped Extra Parts:");
        for(std::size_t p = 0; p < setup.customModularParts.size(); ++p){
            const auto pIdx = setup.customModularParts[p];
            const std::string pName = (pIdx < app.assetCatalog.entries.size()) ? app.assetCatalog.entries[pIdx].name : "Unknown";
            ImGui::BulletText("%s", pName.c_str());
            ImGui::SameLine();
            ImGui::PushID(static_cast<int>(p) + 88000);
            if(ImGui::SmallButton("Remove")){
                setup.customModularParts.erase(setup.customModularParts.begin() + p);
                changed=true;
                --p;
            }
            ImGui::PopID();
        }
    }
    return changed;
}

void drawAnimationClassifier(AppState& app){
    if(ImGui::CollapsingHeader("Animation Classifier & Grammar Studio")){

    uiHelp("Classify, separate viewmodel from playermodel animations, and verify per-game grammars with real-time Dual Rig playback.");

    // --- Section 1: Game Selection & Bulk Game Loader ---
    const auto games = rippedGames(app);
    std::vector<std::string> gameOptions = {"All Games"};
    for (const auto& g : games) gameOptions.push_back(g);

    int selectedGameIdx = 0;
    if (!app.classifierGameFilter.empty()) {
        for (std::size_t i = 0; i < games.size(); ++i) {
            if (lowerText(games[i]) == lowerText(app.classifierGameFilter)) {
                selectedGameIdx = static_cast<int>(i) + 1;
                break;
            }
        }
    }

    ImGui::SetNextItemWidth(140.0f);
    if (ImGui::BeginCombo("Game##classifier_game", gameOptions[selectedGameIdx].c_str())) {
        for (int i = 0; i < static_cast<int>(gameOptions.size()); ++i) {
            const bool isSel = (i == selectedGameIdx);
            if (ImGui::Selectable(gameOptions[i].c_str(), isSel)) {
                selectedGameIdx = i;
                app.classifierGameFilter = (i == 0) ? "" : games[i - 1];
            }
        }
        ImGui::EndCombo();
    }
    ImGui::SameLine();

    const bool hasGameSelected = (selectedGameIdx > 0);
    ImGui::BeginDisabled(!hasGameSelected);
    if (ImGui::Button("Load Entire Game##classifier")) {
        const auto gameName = games[selectedGameIdx - 1];
        const auto root = gameRootDirectoryForGame(app, gameName);
        if (!root.empty()) {
            loadEntireGameDirectory(app, root, gameName);
        } else {
            app.status = "Could not locate root folder for game: " + gameName;
        }
    }
    ImGui::EndDisabled();
    ImGui::SameLine();

    if (ImGui::Button("Load Game Rip Folder...##classifier")) {
        if (const auto folder = chooseFolder()) {
            loadEntireGameDirectory(app, *folder, "");
        }
    }

    // --- Section 2: Reference Rig Setup & Auto-Switch Mode ---
    const std::string activeGame = app.classifierGameFilter.empty() ? (!games.empty() ? games.front() : "Default") : app.classifierGameFilter;
    const bool isDualRig = (app.activeReferenceMode == AppState::ReferenceRigMode::Dual);
    const bool isPlayermodelRig = (app.activeReferenceMode == AppState::ReferenceRigMode::Playermodel);
    const bool isViewmodelRig = (app.activeReferenceMode == AppState::ReferenceRigMode::Viewmodel);

    if (isDualRig) {
        ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.6f, 0.3f, 0.8f, 1.0f));
    }
    if (ImGui::Button(("Dual Rig: Player + Viewmodel [" + activeGame + "]").c_str())) {
        mountGenericDualRig(app, activeGame);
    }
    if (isDualRig) {
        ImGui::PopStyleColor();
    }
    ImGui::SameLine();

    if (isPlayermodelRig) {
        ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.2f, 0.6f, 0.3f, 1.0f));
    }
    if (ImGui::Button(("Playermodel Only [" + activeGame + "]").c_str())) {
        mountGenericPlayermodel(app, activeGame);
    }
    if (isPlayermodelRig) {
        ImGui::PopStyleColor();
    }
    ImGui::SameLine();

    if (isViewmodelRig) {
        ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.2f, 0.5f, 0.75f, 1.0f));
    }
    if (ImGui::Button(("Viewmodel Only [" + activeGame + "]").c_str())) {
        mountGenericViewmodel(app, activeGame);
    }
    if (isViewmodelRig) {
        ImGui::PopStyleColor();
    }
    ImGui::SameLine();

    ImGui::Checkbox("Auto-switch rig on preview", &app.classifierAutoSwitchRig);

    // Custom Reference Models Popdown
    if (ImGui::TreeNode("Customize Reference Models per Game")) {
        auto& setup = app.gameReferenceSetups[activeGame];

        // Player model selector
        const auto currentPm = findGenericPlayermodelForGame(app, activeGame);
        const std::string pmName = (currentPm < app.assetCatalog.entries.size()) ? app.assetCatalog.entries[currentPm].name : "None";
        if (ImGui::BeginCombo("Generic Playermodel", pmName.c_str())) {
            for (std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i) {
                const auto& a = app.assetCatalog.entries[i];
                if (a.role != assets::Role::PlayerModel || (!activeGame.empty() && lowerText(a.game) != lowerText(activeGame))) continue;
                if (ImGui::Selectable(a.name.c_str(), currentPm == i)) {
                    setup.playermodelAsset = i;
                }
            }
            ImGui::EndCombo();
        }

        // Head selector
        const auto currentHead = (currentPm < app.assetCatalog.entries.size()) ? findGenericHeadForPlayermodel(app, activeGame, app.assetCatalog.entries[currentPm]) : static_cast<std::size_t>(-1);
        const std::string headName = (currentHead < app.assetCatalog.entries.size()) ? app.assetCatalog.entries[currentHead].name : "(Attached or Fullbody)";
        if (ImGui::BeginCombo("Player Head", headName.c_str())) {
            if (ImGui::Selectable("None / Embedded in body", currentHead >= app.assetCatalog.entries.size())) {
                setup.headAsset = static_cast<std::size_t>(-1);
            }
            for (std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i) {
                const auto& a = app.assetCatalog.entries[i];
                if (!activeGame.empty() && lowerText(a.game) != lowerText(activeGame)) continue;
                const auto cname = lowerText(a.name);
                if (cname.find("head") == std::string::npos && cname.find("helmet") == std::string::npos) continue;
                if (ImGui::Selectable(a.name.c_str(), currentHead == i)) {
                    setup.headAsset = i;
                }
            }
            ImGui::EndCombo();
        }

        // Viewhands selector
        const auto currentHands = findGenericViewhandsForGame(app, activeGame);
        const std::string handsName = (currentHands < app.assetCatalog.entries.size()) ? app.assetCatalog.entries[currentHands].name : "None";
        if (ImGui::BeginCombo("Generic Viewhands", handsName.c_str())) {
            for (std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i) {
                const auto& a = app.assetCatalog.entries[i];
                if (a.role != assets::Role::ViewHands || (!activeGame.empty() && lowerText(a.game) != lowerText(activeGame))) continue;
                if (ImGui::Selectable(a.name.c_str(), currentHands == i)) {
                    setup.viewhandsAsset = i;
                }
            }
            ImGui::EndCombo();
        }

        // View weapon selector
        const auto currentWpn = findGenericViewWeaponForGame(app, activeGame);
        const std::string wpnName = (currentWpn < app.assetCatalog.entries.size()) ? app.assetCatalog.entries[currentWpn].name : "None";
        if (ImGui::BeginCombo("Generic View Weapon", wpnName.c_str())) {
            for (std::size_t i = 0; i < app.assetCatalog.entries.size(); ++i) {
                const auto& a = app.assetCatalog.entries[i];
                if (a.role != assets::Role::ViewWeapon || (!activeGame.empty() && lowerText(a.game) != lowerText(activeGame))) continue;
                if (ImGui::Selectable(a.name.c_str(), currentWpn == i)) {
                    setup.viewWeaponAsset = i;
                }
            }
            ImGui::EndCombo();
        }

        drawModularPartsCustomization(app, activeGame);

        if (ImGui::SmallButton("Mount Dual Rig Now")) mountGenericDualRig(app, activeGame);
        ImGui::SameLine();
        if (ImGui::SmallButton("Mount Playermodel Now")) mountGenericPlayermodel(app, activeGame);
        ImGui::SameLine();
        if (ImGui::SmallButton("Mount Viewmodel Now")) mountGenericViewmodel(app, activeGame);
        ImGui::SameLine();
        if (ImGui::SmallButton("Reset to Verified Defaults")) {
            setup = {};
            app.status = "Reset reference models to verified defaults for [" + activeGame + "]";
        }
        ImGui::TreePop();
    }

    ImGui::Separator();

    // --- Bot Locomotion Decisions & Directional Deaths Studio ---
    drawBotDecisionMatrix(app);

    ImGui::Separator();

    // --- Section 3: Live Transport & Selected Clip Controls (Streamlined, always visible) ---
    if(app.classifierSelectedClip>=0&&static_cast<std::size_t>(app.classifierSelectedClip)<app.scene.animations.size()){
        auto& clip=app.scene.animations[static_cast<std::size_t>(app.classifierSelectedClip)];
        ImGui::PushID(static_cast<int>(app.classifierSelectedClip)+50000);

        ImGui::TextColored(ImVec4(0.4f, 0.85f, 1.0f, 1.0f), "Active Clip: %s", clip.name.c_str());
        if(!clip.sourceName.empty()&&clip.sourceName!=clip.name){
            ImGui::TextDisabled("Source: %s | Game: %s | Tracks: %zu | Frames: %u", clip.sourceName.c_str(), clip.sourceGame.empty()?"Generic":clip.sourceGame.c_str(), clip.tracks.size(), clip.durationFrames);
        } else {
            ImGui::TextDisabled("Game: %s | Tracks: %zu | Frames: %u", clip.sourceGame.empty()?"Generic":clip.sourceGame.c_str(), clip.tracks.size(), clip.durationFrames);
        }

        // Live Transport Bar
        if(app.playing){
            if(ImGui::Button("Pause##ctrans")){app.playing=false;}
        } else {
            ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.2f, 0.6f, 0.3f, 1.0f));
            if(ImGui::Button("Play Preview##ctrans")){
                ensureReferenceRigForClip(app, clip);
                app.animationIndex=app.previousAnimationIndex=static_cast<std::size_t>(app.classifierSelectedClip);
                app.animationFrame=app.previousAnimationFrame=0;
                app.playing=true;
            }
            ImGui::PopStyleColor();
        }
        ImGui::SameLine();
        if(ImGui::Button("Stop##ctrans")){app.playing=false;app.animationFrame=0;}
        ImGui::SameLine();

        int maxFrame = static_cast<int>(std::max(1u, clip.durationFrames) - 1);
        int curFrame = static_cast<int>(std::clamp(app.animationFrame, 0.0f, static_cast<float>(maxFrame)));
        ImGui::SetNextItemWidth(180.0f);
        if(ImGui::SliderInt("##cframe", &curFrame, 0, maxFrame, "Frame %d")){
            app.animationFrame = static_cast<float>(curFrame);
            app.animationIndex = static_cast<std::size_t>(app.classifierSelectedClip);
        }
        ImGui::SameLine();
        ImGui::TextDisabled("/ %d", maxFrame);

        // 1-Click Quick Classification Buttons
        ImGui::Text("Classify:");
        ImGui::SameLine();
        if(ImGui::SmallButton("VM Fire")){clip.domain=scene::AnimationDomain::ViewModel;clip.action=scene::ActionRole::Fire;clip.role=scene::AnimationRole::Fire;}
        ImGui::SameLine();
        if(ImGui::SmallButton("VM Reload")){clip.domain=scene::AnimationDomain::ViewModel;clip.action=scene::ActionRole::Reload;clip.role=scene::AnimationRole::Reload;}
        ImGui::SameLine();
        if(ImGui::SmallButton("VM ADS")){clip.domain=scene::AnimationDomain::ViewModel;clip.action=scene::ActionRole::Aim;clip.ads=true;}
        ImGui::SameLine();
        if(ImGui::SmallButton("Player Run")){clip.domain=scene::AnimationDomain::PlayerBody;clip.motion=scene::MotionRole::Run;clip.action=scene::ActionRole::None;clip.role=scene::AnimationRole::Run;}
        ImGui::SameLine();
        if(ImGui::SmallButton("Player Walk")){clip.domain=scene::AnimationDomain::PlayerBody;clip.motion=scene::MotionRole::Walk;clip.action=scene::ActionRole::None;clip.role=scene::AnimationRole::Walk;}
        ImGui::SameLine();
        if(ImGui::SmallButton("Player Idle")){clip.domain=scene::AnimationDomain::PlayerBody;clip.motion=scene::MotionRole::Idle;clip.action=scene::ActionRole::None;clip.role=scene::AnimationRole::Idle;}
        ImGui::SameLine();
        if(ImGui::SmallButton("Flinch")){clip.action=scene::ActionRole::Flinch;}
        ImGui::SameLine();
        if(ImGui::SmallButton("Death")){clip.action=scene::ActionRole::Death;clip.role=scene::AnimationRole::Death;}
        ImGui::SameLine();
        if(ImGui::SmallButton("Melee")){clip.action=scene::ActionRole::Melee;clip.role=scene::AnimationRole::Melee;}
        ImGui::SameLine();
        if(ImGui::SmallButton("Unclassify")){clip.domain=scene::AnimationDomain::Other;clip.motion=scene::MotionRole::Unknown;clip.action=scene::ActionRole::None;clip.role=scene::AnimationRole::Unknown;}
        ImGui::SameLine();
        if(ImGui::SmallButton("Re-detect")){scene::classifyAnimationName(clip.sourceName.empty()?clip.name:clip.sourceName,clip);}

        int d=static_cast<int>(clip.domain);
        const char* dOpts[]={"Other","Player Body","Player Torso","Viewmodel"};
        ImGui::SetNextItemWidth(110.0f);
        if(ImGui::Combo("Domain##cedit",&d,dOpts,4))clip.domain=static_cast<scene::AnimationDomain>(d);
        ImGui::SameLine();

        int m=static_cast<int>(clip.motion);
        const char* mOpts[]={"Unknown","Idle","Walk","Run","Sprint","Crawl","Jump","Land","Turn","Transition","Stumble","Climb","Dive","Slide"};
        ImGui::SetNextItemWidth(100.0f);
        if(ImGui::Combo("Motion##cedit",&m,mOpts,14))clip.motion=static_cast<scene::MotionRole>(m);
        ImGui::SameLine();

        int a=static_cast<int>(clip.action);
        const char* aOpts[]={"None","Aim","Fire","Reload","Melee","Flinch","Death","Shellshock","Deploy","Plant","Equip","First Raise","Unequip","Alert","Gesture","Grenade Prep","Throw","Switch Weapon"};
        ImGui::SetNextItemWidth(100.0f);
        if(ImGui::Combo("Action##cedit",&a,aOpts,18))clip.action=static_cast<scene::ActionRole>(a);
        ImGui::SameLine();

        int w=static_cast<int>(clip.weapon);
        const char* wOpts[]={"Any","Rifle","Sniper","Automatic / SMG","Pistol","Dual Wield","Shotgun","M1216","Judge","G11","LMG","Crossbow","Ballistic Knife","Knife","Grenade","Launcher","Riot Shield","Heavy","Minigun","Equipment","Tablet","Radio","Briefcase","RC"};
        ImGui::SetNextItemWidth(110.0f);
        if(ImGui::Combo("Weapon##cedit",&w,wOpts,24))clip.weapon=static_cast<scene::WeaponClass>(w);

        ImGui::Checkbox("ADS##cedit",&clip.ads);ImGui::SameLine();
        ImGui::Checkbox("Looping##cedit",&clip.looping);ImGui::SameLine();
        ImGui::Checkbox("Contextual##cedit",&clip.contextual);

        ImGui::PopID();
        ImGui::Separator();
    }

    // --- Section 4: Search & Filters ---
    ImGui::InputTextWithHint("##classifier_search","Search clips by name or game...",app.classifierSearch.data(),app.classifierSearch.size());
    ImGui::SameLine();
    if(ImGui::Button("Clear Filters")){
        app.classifierSearch.fill(0);
        app.classifierDomainFilter=-1;
        app.classifierActionFilter=-1;
        app.classifierMotionFilter=-1;
        app.classifierWeaponFilter=-1;
        app.classifierUnclassifiedOnly=false;
        app.classifierGameFilter.clear();
    }

    const char* domainNames[]={"All Domains","Other","Player Body","Player Torso","Viewmodel"};
    int domainIdx=app.classifierDomainFilter+1;
    ImGui::SetNextItemWidth(120.0f);
    if(ImGui::Combo("##c_domain",&domainIdx,domainNames,5))app.classifierDomainFilter=domainIdx-1;
    ImGui::SameLine();

    const char* actionNames[]={"All Actions","None","Aim","Fire","Reload","Melee","Flinch","Death","Shellshock","Deploy","Plant","Equip","First Raise","Unequip","Alert","Gesture","Grenade Prep","Throw","Switch Weapon"};
    int actionIdx=app.classifierActionFilter+1;
    ImGui::SetNextItemWidth(120.0f);
    if(ImGui::Combo("##c_action",&actionIdx,actionNames,19))app.classifierActionFilter=actionIdx-1;
    ImGui::SameLine();

    const char* motionNames[]={"All Motions","Unknown","Idle","Walk","Run","Sprint","Crawl","Jump","Land","Turn","Transition","Stumble","Climb","Dive","Slide"};
    int motionIdx=app.classifierMotionFilter+1;
    ImGui::SetNextItemWidth(120.0f);
    if(ImGui::Combo("##c_motion",&motionIdx,motionNames,15))app.classifierMotionFilter=motionIdx-1;
    ImGui::SameLine();

    ImGui::Checkbox("Unclassified only",&app.classifierUnclassifiedOnly);

    if(app.scene.animations.empty()){
        ImGui::TextDisabled("No animations loaded in the current scene. Load an entire game directory or animation folder above.");
        return;
    }

    std::vector<std::size_t> matching;
    matching.reserve(app.scene.animations.size());
    const std::string search=lowerText(app.classifierSearch.data());
    const std::string gameFilter=lowerText(app.classifierGameFilter);
    for(std::size_t i=0;i<app.scene.animations.size();++i){
        const auto& anim=app.scene.animations[i];
        if(!gameFilter.empty()&&!anim.sourceGame.empty()&&lowerText(anim.sourceGame)!=gameFilter)continue;
        if(!search.empty()){
            if(lowerText(anim.name).find(search)==std::string::npos&&lowerText(anim.sourceName).find(search)==std::string::npos&&lowerText(anim.sourceGame).find(search)==std::string::npos)continue;
        }
        if(app.classifierDomainFilter>=0&&static_cast<int>(anim.domain)!=app.classifierDomainFilter)continue;
        if(app.classifierActionFilter>=0&&static_cast<int>(anim.action)!=app.classifierActionFilter)continue;
        if(app.classifierMotionFilter>=0&&static_cast<int>(anim.motion)!=app.classifierMotionFilter)continue;
        if(app.classifierUnclassifiedOnly){
            if(anim.domain!=scene::AnimationDomain::Other&&anim.role!=scene::AnimationRole::Unknown&&anim.action!=scene::ActionRole::None)continue;
        }
        matching.push_back(i);
    }

    // Sort matching rows
    std::sort(matching.begin(), matching.end(), [&](std::size_t a, std::size_t b) {
        const auto& animA = app.scene.animations[a];
        const auto& animB = app.scene.animations[b];
        bool less = false;
        switch(app.classifierSortColumn) {
            case 0: less = (a < b); break;
            case 1: less = (lowerText(animA.name) < lowerText(animB.name)); break;
            case 2: less = (lowerText(animA.sourceGame) < lowerText(animB.sourceGame)); break;
            case 3: less = (static_cast<int>(animA.domain) < static_cast<int>(animB.domain)); break;
            case 4: less = (static_cast<int>(animA.motion) < static_cast<int>(animB.motion)); break;
            case 5: less = (static_cast<int>(animA.action) < static_cast<int>(animB.action)); break;
            case 6: less = (static_cast<int>(animA.weapon) < static_cast<int>(animB.weapon)); break;
            case 7: less = (animA.durationFrames < animB.durationFrames); break;
            default: less = (a < b); break;
        }
        return app.classifierSortAscending ? less : !less;
    });

    ImGui::TextDisabled("Showing %zu of %zu clips (Click column header to sort)",matching.size(),app.scene.animations.size());

    // --- Section 5: Sortable Virtualized Animation Clips Table ---
    if(ImGui::BeginChild("anim_classifier_table_scroll",ImVec2(0,320),ImGuiChildFlags_Borders)){
        if(ImGui::BeginTable("classifier_table",8,ImGuiTableFlags_Borders|ImGuiTableFlags_RowBg|ImGuiTableFlags_Resizable|ImGuiTableFlags_ScrollY|ImGuiTableFlags_Sortable)){
            ImGui::TableSetupColumn("#",ImGuiTableColumnFlags_WidthFixed,30.0f,0);
            ImGui::TableSetupColumn("Name",ImGuiTableColumnFlags_WidthStretch|ImGuiTableColumnFlags_DefaultSort,0.0f,1);
            ImGui::TableSetupColumn("Game",ImGuiTableColumnFlags_WidthFixed,55.0f,2);
            ImGui::TableSetupColumn("Domain",ImGuiTableColumnFlags_WidthFixed,80.0f,3);
            ImGui::TableSetupColumn("Motion",ImGuiTableColumnFlags_WidthFixed,65.0f,4);
            ImGui::TableSetupColumn("Action",ImGuiTableColumnFlags_WidthFixed,70.0f,5);
            ImGui::TableSetupColumn("Weapon",ImGuiTableColumnFlags_WidthFixed,75.0f,6);
            ImGui::TableSetupColumn("Frames",ImGuiTableColumnFlags_WidthFixed,50.0f,7);
            ImGui::TableHeadersRow();

            if (auto* sortSpecs = ImGui::TableGetSortSpecs()) {
                if (sortSpecs->SpecsCount > 0) {
                    app.classifierSortColumn = sortSpecs->Specs->ColumnUserID;
                    app.classifierSortAscending = (sortSpecs->Specs->SortDirection == ImGuiSortDirection_Ascending);
                }
            }

            for(const auto idx:matching){
                const auto& anim=app.scene.animations[idx];
                ImGui::TableNextRow();
                ImGui::TableSetColumnIndex(0);
                ImGui::Text("%zu",idx);

                ImGui::TableSetColumnIndex(1);
                const bool isSelected=(app.classifierSelectedClip==static_cast<int>(idx));
                if(ImGui::Selectable((anim.name+"##crow_"+std::to_string(idx)).c_str(),isSelected,ImGuiSelectableFlags_SpanAllColumns)){
                    app.classifierSelectedClip=static_cast<int>(idx);
                    ensureReferenceRigForClip(app, anim);
                    app.animationIndex=app.previousAnimationIndex=idx;
                    app.animationFrame=0;
                    app.playing=true;
                }

                ImGui::TableSetColumnIndex(2);
                ImGui::Text("%s",anim.sourceGame.empty()?"-":anim.sourceGame.c_str());

                ImGui::TableSetColumnIndex(3);
                ImGui::Text("%s",scene::animationDomainName(anim.domain));

                ImGui::TableSetColumnIndex(4);
                ImGui::Text("%s",scene::motionRoleName(anim.motion));

                ImGui::TableSetColumnIndex(5);
                ImGui::Text("%s",scene::actionRoleName(anim.action));

                ImGui::TableSetColumnIndex(6);
                ImGui::Text("%s",scene::weaponClassName(anim.weapon));

                ImGui::TableSetColumnIndex(7);
                ImGui::Text("%u",anim.durationFrames);
            }
            ImGui::EndTable();
        }
    }
    ImGui::EndChild();
}
}

int classCategoryForWeapon(const AppState& app,const assets::Asset& asset);

bool assetVisible(const AppState& app,const assets::Asset& asset,assets::Role role){
    if(asset.role!=role||(!app.assetGame.empty()&&asset.game!=app.assetGame))return false;
    if((role==assets::Role::ViewWeapon||role==assets::Role::WorldWeapon)&&app.assetWeaponCategory){
        const int category=classCategoryForWeapon(app,asset);
        if(category!=app.assetWeaponCategory)return false;
    }
    if(!app.assetSearch[0])return true;std::string name=asset.name,needle=app.assetSearch.data();
    std::transform(name.begin(),name.end(),name.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});
    std::transform(needle.begin(),needle.end(),needle.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return name.find(needle)!=std::string::npos;
}

void clearAttachedModels(AppState& app){
    app.scene.meshes.erase(std::remove_if(app.scene.meshes.begin(),app.scene.meshes.end(),[](const scene::Mesh& mesh){return mesh.attachmentIndex>=0;}),app.scene.meshes.end());
    app.scene.attachments.clear();app.loadedAttachmentPaths.clear();app.rendererError.clear();if(!uploadMainScene(app))app.status="Equipped models cleared, but GPU upload failed";
}

