std::optional<std::filesystem::path> animationFolderFor(const assets::Asset& asset){
    std::error_code ec;
    for(auto folder=asset.path.parent_path();!folder.empty();folder=folder.parent_path()){
        std::string name=folder.filename().string();std::transform(name.begin(),name.end(),name.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});
        if(name=="models"||name=="xmodels"||name=="model"){
            for(const auto candidate:{"_anims","animations","anims","animtrees","xanim","xanim_export"}){
                const auto animDir=folder.parent_path()/candidate;
                if(std::filesystem::is_directory(animDir,ec)){
                    return animDir;
                }
            }
            return std::nullopt;
        }
        if(folder==folder.root_path())break;
    }
    return std::nullopt;
}

bool pathIsWithin(const std::filesystem::path& path,const std::filesystem::path& folder){
    const auto relative=path.lexically_normal().lexically_relative(folder.lexically_normal());if(relative.empty())return false;const auto first=relative.begin();return first!=relative.end()&&*first!="..";
}

std::string mw3WeaponBaseKey(const assets::Asset& asset){
    const auto game=lowerText(asset.game);if((game!="mw3"&&game!="mw")||asset.role!=assets::Role::ViewWeapon)return {};
    auto name=lowerText(asset.name);if(name.ends_with("_lod0"))name.resize(name.size()-5);if(game=="mw3"){const auto marker=name.find("_iw5");if(marker==std::string::npos)return {};return name.substr(0,marker+4);}const char* camoSuffixes[]={"_brock","_bshdwl","_bwmrpt","_cmdtgr","_stagger"};for(const auto suffix:camoSuffixes)if(name.ends_with(suffix)){name.resize(name.size()-std::char_traits<char>::length(suffix));break;}return name;
}

bool isMw3CamoVariant(const assets::Asset& asset){const auto base=mw3WeaponBaseKey(asset);if(base.empty())return false;auto name=lowerText(asset.name);if(name.ends_with("_lod0"))name.resize(name.size()-5);return name!=base;}

std::string awWeaponFamilyKey(const assets::Asset& asset){
    if(lowerText(asset.game)!="aw"||asset.role!=assets::Role::ViewWeapon)return {};auto name=lowerText(asset.name);if(name.ends_with("_lod0"))name.resize(name.size()-5);if(!name.starts_with("vm_"))return {};const auto end=name.find('_',3);return end==std::string::npos?std::string{}:name.substr(0,end);
}

bool isAwWeaponVariant(const assets::Asset& asset){
    const auto family=awWeaponFamilyKey(asset);if(family.empty())return false;
    auto name=lowerText(asset.name);if(name.ends_with("_lod0"))name.resize(name.size()-5);
    if(name==family||name.ends_with("_base")||name.ends_with("_base_standard")||name.ends_with("_base_default")||name.ends_with("_base_stnd")||name.ends_with("_main_base")||name.ends_with("_dlc_base")||name.ends_with("_dummy_damage"))return false;
    return true;
}

std::string coldWarFamilyForAsset(const assets::Asset& asset){
    const auto game=lowerText(asset.game);
    return (game=="bocw_sp"||game=="bocw"||game=="t9")&&asset.role==assets::Role::ViewWeapon?assets::coldWarWeaponFamily(asset.name):std::string{};
}

bool isColdWarVariant(const AppState& app,const assets::Asset& asset){
    return app.weaponPickerCache.isColdWarVariant(app.assetCatalog,asset);
}

bool drawColdWarVariant(AppState& app,std::size_t& selected){
    if(selected>=app.assetCatalog.entries.size())return false;
    const auto& asset=app.assetCatalog.entries[selected];const auto family=coldWarFamilyForAsset(asset);if(family.empty())return false;
    std::vector<std::size_t> variants;
    for(std::size_t i=0;i<app.assetCatalog.entries.size();++i)if(app.assetCatalog.entries[i].game==asset.game&&coldWarFamilyForAsset(app.assetCatalog.entries[i])==family)variants.push_back(i);
    if(variants.size()<2)return false;
    const auto label=[&](std::size_t i){auto result=assets::coldWarWeaponVariant(app.assetCatalog.entries[i].name);return result.empty()?std::string("Base"):result;};
    bool changed=false;if(ImGui::BeginCombo("Cold War variant",label(selected).c_str())){
        for(const auto i:variants){ImGui::PushID(static_cast<int>(i));if(ImGui::Selectable(label(i).c_str(),i==selected)){selected=i;changed=true;}ImGui::PopID();}ImGui::EndCombo();
    }return changed;
}

bool drawMw3CamoVariant(AppState& app,std::size_t& selected){
    if(selected>=app.assetCatalog.entries.size())return false;const auto base=mw3WeaponBaseKey(app.assetCatalog.entries[selected]);if(base.empty())return false;
    std::vector<std::size_t> variants;for(std::size_t i=0;i<app.assetCatalog.entries.size();++i)if(mw3WeaponBaseKey(app.assetCatalog.entries[i])==base)variants.push_back(i);if(variants.size()<2)return false;
    const auto label=[&](std::size_t index){auto name=lowerText(app.assetCatalog.entries[index].name);if(name.ends_with("_lod0"))name.resize(name.size()-5);if(name==base)return std::string("Base");auto suffix=name.substr(std::min(name.size(),base.size()));if(!suffix.empty()&&suffix.front()=='_')suffix.erase(suffix.begin());return suffix;};
    const auto preview=label(selected);bool changed=false;if(ImGui::BeginCombo("Weapon camo model",preview.c_str())){for(const auto index:variants){const auto variant=label(index);if(ImGui::Selectable(variant.c_str(),selected==index)){selected=index;changed=true;}}ImGui::EndCombo();}return changed;
}

bool drawAwWeaponVariant(AppState& app,std::size_t& selected){
    if(selected>=app.assetCatalog.entries.size())return false;const auto family=awWeaponFamilyKey(app.assetCatalog.entries[selected]);if(family.empty())return false;std::vector<std::size_t> variants;for(std::size_t i=0;i<app.assetCatalog.entries.size();++i)if(awWeaponFamilyKey(app.assetCatalog.entries[i])==family)variants.push_back(i);if(variants.size()<2)return false;
    const auto label=[&](std::size_t index){auto name=lowerText(app.assetCatalog.entries[index].name);if(name.ends_with("_lod0"))name.resize(name.size()-5);auto suffix=name.substr(std::min(name.size(),family.size()));if(!suffix.empty()&&suffix.front()=='_')suffix.erase(suffix.begin());return suffix.empty()?std::string("Base"):suffix;};const auto preview=label(selected);bool changed=false;if(ImGui::BeginCombo("AW weapon variant",preview.c_str())){for(const auto index:variants){const auto variant=label(index);if(ImGui::Selectable(variant.c_str(),selected==index)){selected=index;changed=true;}}ImGui::EndCombo();}return changed;
}

bool assetCombo(AppState& app,const char* label,assets::Role role,std::size_t& selected){
    const char* preview="Select asset";if(selected<app.assetCatalog.entries.size()&&app.assetCatalog.entries[selected].role==role)preview=app.assetCatalog.entries[selected].name.c_str();bool changed=false;
    if(ImGui::BeginCombo(label,preview)){
        for(std::size_t i=0;i<app.assetCatalog.entries.size();++i){const auto& asset=app.assetCatalog.entries[i];if(!assetVisible(app,asset,role)||(!app.showAllWeaponVariants&&role==assets::Role::ViewWeapon&&(isMw3CamoVariant(asset)||isAwWeaponVariant(asset))))continue;ImGui::PushID(static_cast<int>(i));
            const std::string entryLabel=(asset.game.empty()?std::string{}:"["+asset.game+"] ")+asset.name;
            if(ImGui::Selectable(entryLabel.c_str(),selected==i)){selected=i;changed=true;}ImGui::PopID();}
        ImGui::EndCombo();
    }
    return changed;
}

enum class Bo2Class { Assault, Smg, Lmg, Shotgun, Sniper, Secondary };

Bo2Class bo2ClassForWeapon(const assets::Asset& asset){const auto name=lowerText(asset.name);
    if(name.find("_ar_")!=std::string::npos)return Bo2Class::Assault; // HK416 is intentionally here.
    if(name.find("_smg_")!=std::string::npos)return Bo2Class::Smg;if(name.find("_lmg_")!=std::string::npos)return Bo2Class::Lmg;
    if(name.find("_shotty_")!=std::string::npos||name.find("shotgun")!=std::string::npos)return Bo2Class::Shotgun;
    if(name.find("_sniper_")!=std::string::npos)return Bo2Class::Sniper;
    const auto inferred=weapon::inferArchetype(asset.name);if(weapon::isSniper(inferred))return Bo2Class::Sniper;return Bo2Class::Secondary;
}

const char* bo2ClassName(Bo2Class value){switch(value){case Bo2Class::Assault:return "Assault";case Bo2Class::Smg:return "SMG";case Bo2Class::Lmg:return "LMG";case Bo2Class::Shotgun:return "Shotgun";case Bo2Class::Sniper:return "Sniper";default:return "Secondary";}}

std::size_t findCatalogAsset(const AppState& app,assets::Role role,std::string_view game,std::string_view namePart){
    for(std::size_t i=0;i<app.assetCatalog.entries.size();++i){const auto& asset=app.assetCatalog.entries[i];if(asset.role==role&&lowerText(asset.game)==lowerText(std::string(game))&&lowerText(asset.name).find(namePart)!=std::string::npos)return i;}return static_cast<std::size_t>(-1);
}

std::string modelKey(std::string value){value=lowerText(std::move(value));if(value.ends_with("_lod0"))value.resize(value.size()-5);return value;}

std::size_t findCatalogModelExact(const AppState& app,assets::Role role,std::string_view game,std::string_view model){
    const auto wanted=modelKey(std::string(model));for(std::size_t i=0;i<app.assetCatalog.entries.size();++i){const auto& asset=app.assetCatalog.entries[i];if(asset.role==role&&lowerText(asset.game)==lowerText(std::string(game))&&modelKey(asset.name)==wanted)return i;}return static_cast<std::size_t>(-1);
}

int classCategoryForWeapon(const AppState& app,const assets::Asset& asset){
    static std::unordered_map<std::string,int> cache;const auto key=lowerText(asset.path.string());if(const auto found=cache.find(key);found!=cache.end())return found->second;
    int category=0;
    const auto cat=lowerText(asset.category);
    if(!cat.empty()){
        if(cat.find("sniper")!=std::string::npos||cat.find("marksman")!=std::string::npos)category=5;
        else if(cat.find("assault")!=std::string::npos||cat.find("rifle")!=std::string::npos)category=1;
        else if(cat.find("smg")!=std::string::npos||cat.find("submachine")!=std::string::npos)category=2;
        else if(cat.find("lmg")!=std::string::npos||cat.find("machine gun")!=std::string::npos)category=3;
        else if(cat.find("shotgun")!=std::string::npos)category=4;
        else if(cat.find("pistol")!=std::string::npos||cat.find("handgun")!=std::string::npos||cat.find("machine_pistol")!=std::string::npos)category=6;
        else if(cat.find("launcher")!=std::string::npos)category=7;
        else if(cat.find("melee")!=std::string::npos||cat.find("grenade")!=std::string::npos||cat.find("equipment")!=std::string::npos||cat.find("special")!=std::string::npos)category=8;
    }
    if(category==0){
        auto archetype=weapon::inferArchetype(asset.name);if(const auto source=legacyWeaponFileForAsset(app,asset)){static std::unordered_map<std::string,weapon::Archetype> sourceCache;const auto sourceKey=lowerText(source->string());if(const auto found=sourceCache.find(sourceKey);found!=sourceCache.end())archetype=found->second;else{weapon::Profile profile;std::string error;if(weapon::importLegacyWeaponFile(profile,*source,error))archetype=profile.archetype;sourceCache[sourceKey]=archetype;}}
        category=8;switch(archetype){case weapon::Archetype::Rifle:category=1;break;case weapon::Archetype::Smg:category=2;break;case weapon::Archetype::Lmg:category=3;break;case weapon::Archetype::Shotgun:category=4;break;case weapon::Archetype::BoltSniper:case weapon::Archetype::BoltIndividualSniper:case weapon::Archetype::SemiSniper:category=5;break;case weapon::Archetype::Pistol:case weapon::Archetype::DualWield:category=6;break;case weapon::Archetype::Launcher:category=7;break;default:break;}
    }
    cache[key]=category;return category;
}

scene::WeaponClass gameplayWeaponClass(const weapon::Profile& profile,const assets::Asset& asset){
    const auto name=lowerText(asset.name);
    if(name.find("judge")!=std::string::npos)return scene::WeaponClass::Judge;
    if(name.find("srm1216")!=std::string::npos||name.find("m1216")!=std::string::npos)return scene::WeaponClass::M1216;
    if(name.find("crossbow")!=std::string::npos)return scene::WeaponClass::Crossbow;
    if(name.find("ballistic")!=std::string::npos)return scene::WeaponClass::BallisticKnife;
    switch(profile.archetype){
        case weapon::Archetype::Rifle:return scene::WeaponClass::Rifle;
        case weapon::Archetype::Smg:return scene::WeaponClass::Automatic;
        case weapon::Archetype::Lmg:return scene::WeaponClass::LMG;
        case weapon::Archetype::Shotgun:return scene::WeaponClass::Shotgun;
        case weapon::Archetype::BoltSniper:
        case weapon::Archetype::BoltIndividualSniper:
        case weapon::Archetype::SemiSniper:return scene::WeaponClass::Sniper;
        case weapon::Archetype::Pistol:return scene::WeaponClass::Pistol;
        case weapon::Archetype::DualWield:return scene::WeaponClass::DualWield;
        case weapon::Archetype::Launcher:return scene::WeaponClass::Launcher;
        case weapon::Archetype::Equipment:return scene::WeaponClass::Equipment;
        default:return scene::WeaponClass::Any;
    }
}

void restoreEngineViewHeight(AppState& app){
    // The imported actor's eye/head bones describe the rendered body, not the
    // playerState camera. Classic IW movement drives the camera from viewHeight.
    app.actorStandingViewHeight=gameplay::iw::viewHeight(scene::Stance::Stand);
    const float ratio=gameplay::iw::viewHeight(app.gameplayStance)/gameplay::iw::viewHeight(scene::Stance::Stand);
    app.actorViewHeight=app.actorViewHeightStart=app.actorViewHeightTarget=app.actorStandingViewHeight*ratio;
    app.actorViewHeightElapsed=app.actorViewHeightDuration=0;
}

std::size_t classHandsForWeapon(const AppState& app,const assets::Asset& asset){
    if(app.classViewhandsOverride<app.assetCatalog.entries.size()&&app.assetCatalog.entries[app.classViewhandsOverride].role==assets::Role::ViewHands)return app.classViewhandsOverride;
    if(!asset.customPackageId.empty())for(std::size_t i=0;i<app.assetCatalog.entries.size();++i)if(app.assetCatalog.entries[i].role==assets::Role::ViewHands&&app.assetCatalog.entries[i].customPackageId==asset.customPackageId)return i;
    const auto profile=generatedWeaponProfile(app,asset);if(!profile.handModelName.empty())if(const auto exact=findCatalogModelExact(app,assets::Role::ViewHands,asset.game,profile.handModelName);exact<app.assetCatalog.entries.size())return exact;
    const auto g=lowerText(asset.game);
    if(g=="bo2"){const auto weaponClass=bo2ClassForWeapon(asset);const bool shortSleeves=weaponClass==Bo2Class::Smg||weaponClass==Bo2Class::Shotgun;const std::string faction=app.classFaction==0?"c_usa_mp_seal6_":"c_mul_mp_pmc_";return findCatalogAsset(app,assets::Role::ViewHands,asset.game,faction+(shortSleeves?"shortsleeve":"longsleeve")+"_viewhands");}
    if(g=="mw3"||g=="iw5"){
        if(const auto delta=findCatalogAsset(app,assets::Role::ViewHands,asset.game,"viewhands_delta");delta<app.assetCatalog.entries.size())return delta;
    }
    if(g=="iw_sp"||g=="iw7"||g=="iw")if(const auto base=findCatalogModelExact(app,assets::Role::ViewHands,asset.game,"viewmodel_base_viewhands_iw7");base<app.assetCatalog.entries.size())return base;
    if(const auto base=findCatalogModelExact(app,assets::Role::ViewHands,asset.game,"viewmodel_base_viewhands");base<app.assetCatalog.entries.size())return base;
    for(std::size_t i=0;i<app.assetCatalog.entries.size();++i)if(app.assetCatalog.entries[i].role==assets::Role::ViewHands&&lowerText(app.assetCatalog.entries[i].game)==g)return i;
    return static_cast<std::size_t>(-1);
}

bool shouldAutoLoadRigPart(const AppState& app,const assets::Asset& weaponAsset,const assets::Asset& part){
    const auto name=lowerText(part.name);
    const auto game=lowerText(weaponAsset.game);
    if(game=="bocw_sp"||game=="bocw"||game=="coldwar"||game=="t9")
        return assets::isPreferredColdWarRigPart(app.assetCatalog,weaponAsset,part);
    if(game=="aw"&&part.game==weaponAsset.game){
        const auto base=lowerText(weaponAsset.name);
        for(const auto family:{"vm_titan45_","vm_mp443_"})if(base.starts_with(std::string(family)+"base"))
            return name==std::string(family)+"damage_"+base.substr(std::char_traits<char>::length(family));
    }
    if(game=="iw_sp"||game=="iw7"||game=="iw"){
        if(!assets::isDefaultIwRigPart(weaponAsset.name,part.name))return false;
        // Some complex_1 exports are complete camo variants, not receiver parts.
        // Preserve genuine modules and manual selection; never stack an identical skin automatically.
        if(name.find("_complex_")!=std::string::npos){
            const auto base=cast::Document::load(weaponAsset.path);
            const auto candidate=cast::Document::load(part.path);
            if(!base.valid()||!candidate.valid())return false;
            if(scene::sameRigGeometry(scene::buildScene(base),scene::buildScene(candidate)))return false;
        }
        return true;
    }
    const bool standardMagazine=name.find("attach_mag_")!=std::string::npos&&name.find("fastmag")==std::string::npos;
    if(standardMagazine)return true;
    if(name.find("scope")==std::string::npos)return false;
    static const std::unordered_set<std::string> generic{"ar","smg","lmg","sniper","pistol","shotty","shotgun","scope","view","world"};
    for(const auto& key:part.compatibilityKeys)if(key.size()>=3&&!generic.contains(key)&&std::find(weaponAsset.compatibilityKeys.begin(),weaponAsset.compatibilityKeys.end(),key)!=weaponAsset.compatibilityKeys.end())return true;
    return false;
}

void ensureColdWarAnimationSources(AppState& app,const assets::Asset& asset){
    const auto game=lowerText(asset.game);if(game!="bocw_sp"&&game!="bocw"&&game!="t9")return;
    const auto folder=animationFolderFor(asset);const auto prefix=animationPrefixForWeapon(asset);if(!folder||prefix.empty())return;
    std::unordered_set<std::string> loaded;for(const auto& p:app.animationSources)loaded.insert(lowerText(p.lexically_normal().string()));
    std::vector<std::filesystem::path> files;std::error_code ec;
    for(std::filesystem::recursive_directory_iterator it(*folder,std::filesystem::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec)){
        if(ec){ec.clear();continue;}if(!it->is_regular_file(ec))continue;const auto name=lowerText(it->path().filename().string());
        if(name.starts_with(prefix)&&name.ends_with(".cast")&&!loaded.contains(lowerText(it->path().lexically_normal().string())))files.push_back(it->path());
    }
    std::sort(files.begin(),files.end());for(const auto& p:files){auto doc=cast::Document::load(p);if(!doc.valid())continue;app.animationSources.push_back(p);app.animationDocuments.push_back(std::move(doc));}
}
bool equipNativeCodm(AppState& app,std::size_t weaponIndex){
    if(weaponIndex>=app.assetCatalog.entries.size()||lowerText(app.assetCatalog.entries[weaponIndex].game)!="codm")return false;
    const auto& weapon=app.assetCatalog.entries[weaponIndex];
    std::string metadataError;if(!scene::codm::nativeMetres(weapon.path,metadataError)){const auto meta=scene::codm::metadata(weapon.path);if(meta.is_object()&&meta.contains("t6Compatible")&&meta["t6Compatible"]==true)return false;app.status=metadataError;return true;}
    if(app.selectedBaseAsset>=app.assetCatalog.entries.size())return true;
    const bool legacyHands=lowerText(app.assetCatalog.entries[app.selectedBaseAsset].game)!="codm";
    const auto handPath=app.assetCatalog.entries[app.selectedBaseAsset].path;
    auto weaponDocument=cast::Document::load(weapon.path),handsDocument=cast::Document::load(handPath);scene::CastScene composite;
    auto referenceDocument=handsDocument;
    if(legacyHands){
        const auto ref=cadence::codm::referenceHands(app.assetCatalog);
        if(!ref){app.status="CODM adapter requires C_M_Ghost_1P native viewhands in the loaded CODM catalog (codm_viewhands_ or viewhands_ prefix).";return true;}
        referenceDocument=cast::Document::load(app.assetCatalog.entries[*ref].path);
    }
    if(!scene::codm::assemble(weaponDocument,referenceDocument,composite,metadataError)){app.status=metadataError;return true;}
    if(legacyHands){auto reference=scene::buildScene(referenceDocument);scene::codm::normalizeToCentimetres(reference,scene::codm::presentationScale);if(!scene::codm::fitLegacyHands(composite,reference,handsDocument,metadataError)){app.status="Unsupported CODM hand adapter: "+metadataError;return true;}}
    loadFile(app,handPath);app.scene=std::move(composite);app.animationSources.clear();app.animationDocuments.clear();app.loadedRigModelPaths={weapon.path};app.equippedRigAssets={weaponIndex};
    const auto folder=animationFolderFor(weapon);const auto prefix=lowerText(weapon.name)+"_";
    std::vector<std::filesystem::path> files;std::error_code ec;
    std::vector<std::string> codmWeaponStems;
    for(const auto& a:app.assetCatalog.entries)if(lowerText(a.game)=="codm"&&a.role==assets::Role::ViewWeapon)codmWeaponStems.push_back(a.name);
    if(folder)for(std::filesystem::recursive_directory_iterator it(*folder,ec),end;it!=end;it.increment(ec)){
        if(ec){ec.clear();continue;}const auto name=lowerText(it->path().filename().string());
        if(it->is_regular_file(ec)&&name.ends_with(".cast")&&!name.ends_with("_camera.cast")&&cadence::codm_actions::belongsToWeapon(it->path().stem().string(),weapon.name,codmWeaponStems))files.push_back(it->path());
    }
    std::sort(files.begin(),files.end());for(const auto& path:files){
        const auto meta=scene::codm::metadata(path);if(!meta.is_object()||!meta.contains("t6Compatible")||meta["t6Compatible"]!=false){app.scene.warnings.push_back("Skipped CODM clip with missing/native-incompatible metadata: "+path.filename().string());continue;}
        auto doc=cast::Document::load(path);if(!doc.valid())continue;const auto first=app.scene.animations.size();scene::appendAnimations(doc,app.scene);tagAnimationGame(app.scene,first,path);app.animationSources.push_back(path);app.animationDocuments.push_back(std::move(doc));
    }
    cadence::codm_actions::prepare(app.scene);
    activateWeaponProfile(app,generatedWeaponProfile(app,weapon));populateDefaultDiscoveredAnimations(app,app.weaponProfile,weapon);app.weaponTiming=app.weaponProfile.stats;app.viewmodelAnimationPrefix=prefix;
    // populate already handles aliases while preserving valid explicit overrides.
    // Do not run a second alias pass that silently replaces those overrides.
    for(const char* slot:{"idle","fire","reload","pullout","putaway","ads_up","ads_down"})
        if(!app.weaponProfile.animations.contains(slot))app.scene.warnings.push_back(std::string("CODM missing exported action: ")+slot+" ("+weapon.name+")");
    app.assetFirstPerson=true;app.viewmodelCamera=true;app.selectedWeaponAsset=weaponIndex;
    app.actionActive=false;app.actionOverlay=false;app.transitioning=false;
    selectViewmodelIdle(app,weapon);if(!app.deferSceneUpload)uploadMainScene(app);
    app.status="CODM: global fit 1.740741x, "+std::to_string(app.scene.animations.size())+" clips; "+(legacyHands?"runtime anatomical hand adapter":"native hand binding");
    if(app.scene.animations.empty()){
        app.status="CODM incomplete export: no weapon animation clips for "+weapon.name+". Camera-only clips cannot supply an idle pose; re-export the weapon animation set.";
        app.scene.warnings.push_back(app.status);
    }
    return true;
}

#include "app/PointBlankEquipment.inc"
void equipViewWeapon(AppState& app,std::size_t weaponIndex,AppState* notifyApp,std::optional<bool> dualOverride){
    if(equipNativePointBlank(app,weaponIndex))return;
    if(equipNativeCodm(app,weaponIndex))return;
    AppState& logger = notifyApp ? *notifyApp : app;
    if(weaponIndex>=app.assetCatalog.entries.size()||app.selectedBaseAsset>=app.assetCatalog.entries.size())return;
    const auto& selectedWeapon=app.assetCatalog.entries[weaponIndex];
    if(auditedWeaponGame(selectedWeapon.game))app.selectedWeaponAsset=weaponIndex;
    logLoading(logger, "Configuring weapon profile: [" + selectedWeapon.game + "] " + selectedWeapon.name);
    activateWeaponProfile(app,generatedWeaponProfile(app,selectedWeapon,{},!auditedWeaponGame(selectedWeapon.game)));
    if(dualOverride)app.weaponProfile.archetype=*dualOverride?weapon::Archetype::DualWield:weapon::Archetype::Pistol;
    const bool requestedDual=app.weaponProfile.archetype==weapon::Archetype::DualWield&&(lowerText(selectedWeapon.game)=="bo2"||lowerText(selectedWeapon.game)=="mw3");
    app.dualLeftNextFireTime=0;app.previousDualLeft=false;app.pendingDualShots.clear();app.dualMuzzleFlashTime={};
    app.gameplayRechamber=false;
    app.gameplayWeapon=gameplayWeaponClass(app.weaponProfile,selectedWeapon);
    const auto sources=app.animationSources;
    auto documents=std::move(app.animationDocuments);
    logLoading(logger, "Loading base viewhands: " + app.assetCatalog.entries[app.selectedBaseAsset].name);
    loadFile(app,app.assetCatalog.entries[app.selectedBaseAsset].path);
    app.animationSources=sources;
    app.animationDocuments=std::move(documents);
    std::optional<scene::Mat4> sourceWeaponMount;float importedWeaponScale=1.0f;
    const auto weaponGame=lowerText(selectedWeapon.game),handsGame=activeViewhandsGame(app);
    if(weaponGame=="cs2"&&!handsGame.empty()&&handsGame!="cs2")if(const auto* sourceHands=sourceViewhandsSkeletonForGame(app,weaponGame)){
        const auto socket=sourceHands->boneByCanonicalName.find("wpn");
        if(socket!=sourceHands->boneByCanonicalName.end()){sourceWeaponMount=scene::Mat4::identity();importedWeaponScale=crossRigWeaponScale(app.scene.skeleton,*sourceHands);logLoading(logger,"Scaling CS2 weapon coordinates for "+handsGame+" hands at "+std::to_string(importedWeaponScale)+"x");}
    }
    logLoading(logger, "Mounting weapon model: " + selectedWeapon.name);
    addRigModelFile(app,app.assetCatalog.entries[weaponIndex].path,false,sourceWeaponMount,importedWeaponScale);
    app.equippedRigAssets.push_back(weaponIndex);
    if(requestedDual&&weaponGame=="bo2"){
        auto name=selectedWeapon.path.stem().string();const auto view=name.find("_view");
        if(view!=std::string::npos&&name.find("_view_lh")==std::string::npos){name.insert(view+5,"_lh");auto folder=selectedWeapon.path.parent_path().filename().string()+"_lh";const auto left=selectedWeapon.path.parent_path().parent_path()/folder/(name+".cast");if(std::filesystem::is_regular_file(left))addRigModelFile(app,left,false);else{app.status="Dual wield: missing dedicated BO2 left-hand model";return;}}
    }
    for(const auto index:app.assetCatalog.compatibleAttachments(weaponIndex)){
        if(shouldAutoLoadRigPart(app,selectedWeapon,app.assetCatalog.entries[index])){
            logLoading(logger, "Mounting attachment: " + app.assetCatalog.entries[index].name);
            addRigModelFile(app,app.assetCatalog.entries[index].path,false,sourceWeaponMount,importedWeaponScale);
            app.equippedRigAssets.push_back(index);
        }
    }
    for(std::size_t index=0;index<app.assetCatalog.entries.size();++index){
        const auto& candidate=app.assetCatalog.entries[index];
        if(weaponGame=="aw"&&candidate.role==assets::Role::ViewWeapon&&shouldAutoLoadRigPart(app,selectedWeapon,candidate)){
            addRigModelFile(app,candidate.path,false,sourceWeaponMount,importedWeaponScale);app.equippedRigAssets.push_back(index);continue;
        }
        if(requestedDual||candidate.game!=app.assetCatalog.entries[weaponIndex].game||lowerText(candidate.name).find("t6_wpn_knife_base_view")==std::string::npos)continue;
        addRigModelFile(app,candidate.path,false,sourceWeaponMount,importedWeaponScale);
        app.equippedRigAssets.push_back(index);
        break;
    }
    if(const auto folder=animationFolderFor(selectedWeapon)){
        const auto prefix=animationPrefixForWeapon(selectedWeapon);
        const auto keys=viewmodelKeys(selectedWeapon);
        bool hasWeaponAnims=false;
        for(const auto& clip:app.scene.animations){
            const auto src=lowerText(clip.sourceName);
            if(!prefix.empty()&&src.starts_with(prefix)){hasWeaponAnims=true;break;}
            for(const auto& k:keys)if(src.find("_"+k+"_")!=std::string::npos||src.starts_with("viewmodel_"+k+"_")||src.starts_with("vm_"+k+"_")||src.ends_with("_"+k+".cast")||src.ends_with("_"+k+"_model.cast")){hasWeaponAnims=true;break;}
        }
        if(!hasWeaponAnims){
            logLoading(logger, "Scanning animation catalog in " + folder->filename().string() + "...");
            std::vector<std::filesystem::path> animFiles;
            if(app.classAnimationIndex&&weaponGame!="cs2"&&handsGame!="cs2"){
                for(const auto& entry:app.classAnimationIndex->files(*folder))
                    if(assets::AnimationFileIndex::matches(entry,prefix,keys))animFiles.push_back(entry.path);
            }else{
            std::error_code ec;
            for(std::filesystem::recursive_directory_iterator it(*folder,std::filesystem::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec)){
                if(ec){ec.clear();continue;}
                if(it->is_regular_file(ec)&&it->path().extension()==".cast"){
                    const auto fname=lowerText(it->path().filename().string());
                    bool match=!prefix.empty()&&fname.starts_with(prefix);
                    if(!match)for(const auto& k:keys){
                        if(fname.find("_"+k+"_")!=std::string::npos||fname.starts_with("viewmodel_"+k+"_")||fname.starts_with("vm_"+k+"_")||
                           fname.ends_with("_"+k+".cast")||fname.ends_with("_"+k+"_model.cast")){
                            match=true;break;
                        }
                    }
                    if(!match){
                        for(auto parent=it->path().parent_path();parent!=*folder&&!parent.empty();parent=parent.parent_path()){
                            const auto pName=lowerText(parent.filename().string());
                            for(const auto& k:keys){
                                if(pName==k||pName==prefix||pName=="knife_"+k||pName=="weapon_"+k||pName=="viewmodel_"+k||pName=="vm_"+k){
                                    match=true;break;
                                }
                            }
                            if(match)break;
                        }
                    }
                    if(match)animFiles.push_back(it->path());
                }
            }
            }
            std::sort(animFiles.begin(),animFiles.end());
            if(weaponGame=="bocw_sp"||weaponGame=="bocw"||weaponGame=="t9"||auditedWeaponGame(weaponGame)){
                std::erase_if(animFiles,[&](const auto& p){return !animationSourceMatchesWeapon(p,selectedWeapon);});
            }
            logLoading(logger, "Found " + std::to_string(animFiles.size()) + " animation files for " + selectedWeapon.name);
            for(std::size_t ai = 0; ai < animFiles.size(); ++ai){
                const auto& p = animFiles[ai];
                auto doc=cast::Document::load(p);
                if(!doc.valid())continue;
                if(weaponGame=="bocw_sp"||weaponGame=="bocw"||weaponGame=="t9"){
                    // Final merge retargets once, after the composite skeleton is complete.
                    if(std::find(app.animationSources.begin(),app.animationSources.end(),p)==app.animationSources.end()){
                        app.animationSources.push_back(p);app.animationDocuments.push_back(std::move(doc));
                    }
                    continue;
                }
                const auto before=app.scene.animations.size();
                const auto added=scene::appendAnimations(doc,app.scene);
                tagAnimationGame(app.scene,before,p);
                const bool retargeted=retargetNewAnimations(app,p,before,&doc);
                if(added&&std::find(app.animationSources.begin(),app.animationSources.end(),p)==app.animationSources.end()){
                    app.animationSources.push_back(p);
                    app.animationDocuments.push_back(std::move(doc));
                }
                if (ai % 6 == 0 || ai + 1 == animFiles.size()) {
                    logLoading(logger, std::string(retargeted?"Retargeted clip [":"Indexed clip: ")+(retargeted?gameFromExportPath(p)+" -> "+activeViewhandsGame(app)+"] ":std::string{})+p.filename().string());
                }
            }
        }
    }
    ensureColdWarAnimationSources(app,selectedWeapon);
    if(requestedDual&&weaponGame=="mw3"&&cadence::dual::duplicateMw3(app.scene))app.loadedRigModelPaths.push_back(selectedWeapon.path);
    finishRigMerge(app,&selectedWeapon);
    if(!app.scene.dualWield)populateDefaultDiscoveredAnimations(app, app.weaponProfile, selectedWeapon);
    if(requestedDual){std::string error;if(!cadence::dual::prepare(app.scene,app.weaponProfile,animationPrefixForWeapon(selectedWeapon),weaponGame=="mw3",error)){app.status=error;return;}if(!app.deferSceneUpload)uploadMainScene(app);}
    app.weaponTiming=app.weaponProfile.stats;
    app.viewmodelAnimationPrefix = app.weaponProfile.animationPrefix.empty() ? animationPrefixForWeapon(selectedWeapon) : app.weaponProfile.animationPrefix;
    if(app.activeClassSlot >= 0 && app.activeClassSlot < 3 && app.classSlotRigs[app.activeClassSlot]){
        app.classSlotRigs[app.activeClassSlot]->profile = app.weaponProfile;
        app.classSlotRigs[app.activeClassSlot]->animationPrefix = app.viewmodelAnimationPrefix;
        if(dualOverride){app.classSlotRigs[app.activeClassSlot]->idleAnimation=static_cast<size_t>(-1);app.classSlotRigs[app.activeClassSlot]->adsDownAnimation=static_cast<size_t>(-1);}
    }
    if(!selectedWeapon.customManifest.empty()){
        std::string error;
        if(!applyCustomContentPackage(app,selectedWeapon.customManifest,error))
            app.status="Custom gun load failed: "+error;
        else if(!error.empty())
            app.status=error;
    }
    selectViewmodelIdle(app,app.assetCatalog.entries[weaponIndex]);
    if(auditedWeaponGame(selectedWeapon.game)&&app.animationIndex>=app.scene.animations.size())logLoading(logger,app.status);
}

void queueBaseModelLoad(AppState& app,const std::filesystem::path& path){
    app.pendingModelKind=1;app.pendingModelDelay=1;app.pendingModelStage=0;app.pendingBaseModelPath=path;
    app.loadingActive=true;app.loadingProgress=0.05f;app.loadingStartTime=glfwGetTime();
    app.loadingLabel="Loading Model";app.loadingDetail=path.filename().string();
    app.status="Preparing model "+path.filename().string();
    {
        std::lock_guard<std::mutex> lock(app.loadingLogMutex);
        app.loadingLogs.clear();
    }
    logLoading(app, "Initiating model load: " + path.filename().string(), 0.10f);
}

void queueViewWeaponLoad(AppState& app,std::size_t weaponIndex){
    if(weaponIndex>=app.assetCatalog.entries.size()||app.selectedBaseAsset>=app.assetCatalog.entries.size())return;
    app.pendingModelKind=2;app.pendingModelDelay=1;app.pendingModelStage=0;app.pendingViewWeapon=weaponIndex;
    app.pendingRigAssets.clear();app.pendingRigCursor=0;
    app.loadingActive=true;app.loadingProgress=0.05f;app.loadingStartTime=glfwGetTime();
    app.loadingLabel="Loading View Weapon";app.loadingDetail=app.assetCatalog.entries[weaponIndex].name;
    app.status="Preparing composite weapon rig";
    {
        std::lock_guard<std::mutex> lock(app.loadingLogMutex);
        app.loadingLogs.clear();
    }
    logLoading(app, "Equipping view weapon: [" + app.assetCatalog.entries[weaponIndex].game + "] " + app.assetCatalog.entries[weaponIndex].name, 0.10f);
    logLoading(app, "Base viewhands: [" + app.assetCatalog.entries[app.selectedBaseAsset].game + "] " + app.assetCatalog.entries[app.selectedBaseAsset].name, 0.15f);
}

void processPendingModelLoad(AppState& app){
    if(!app.pendingModelKind)return;if(app.pendingModelDelay>0){--app.pendingModelDelay;return;}
    if(app.pendingModelKind==1){
        const auto path=app.pendingBaseModelPath;
        logLoading(app, "Parsing Cast model file: " + path.filename().string(), 0.50f);
        loadFile(app,path);
        logLoading(app, "Model loaded successfully", 1.0f);
        app.pendingModelKind=0;app.loadingActive=false;app.loadingVisibleUntil=glfwGetTime()+1.0;
        return;
    }
    if(app.pendingViewWeapon>=app.assetCatalog.entries.size()||app.selectedBaseAsset>=app.assetCatalog.entries.size()){app.pendingModelKind=0;app.loadingActive=false;return;}
    const auto weaponIndex=app.pendingViewWeapon;
    if(app.pendingModelStage==0){
        // The picker and class loader must share discovery/assembly. The old
        // staged path only reused previously loaded animations for these games.
        if(auditedWeaponGame(app.assetCatalog.entries[weaponIndex].game)){
            equipViewWeapon(app,weaponIndex,nullptr);
            app.pendingModelKind=app.pendingModelStage=0;app.loadingActive=false;app.loadingVisibleUntil=glfwGetTime()+1.0;
            return;
        }
        if(equipNativePointBlank(app,weaponIndex)||equipNativeCodm(app,weaponIndex)){app.pendingModelKind=app.pendingModelStage=0;app.loadingActive=false;app.loadingVisibleUntil=glfwGetTime()+1.0;return;}
        const auto& selectedWeapon=app.assetCatalog.entries[weaponIndex];
        activateWeaponProfile(app,generatedWeaponProfile(app,selectedWeapon));
        app.gameplayRechamber=false;app.gameplayWeapon=gameplayWeaponClass(app.weaponProfile,selectedWeapon);
        const auto sources=app.animationSources;auto documents=std::move(app.animationDocuments);
        logLoading(app, "Loading viewhands mesh: " + app.assetCatalog.entries[app.selectedBaseAsset].name, 0.20f);
        loadFile(app,app.assetCatalog.entries[app.selectedBaseAsset].path);
        app.animationSources=sources;app.animationDocuments=std::move(documents);
        app.pendingRigAssets.push_back(weaponIndex);
        for(const auto index:app.assetCatalog.compatibleAttachments(weaponIndex))
            if(shouldAutoLoadRigPart(app,selectedWeapon,app.assetCatalog.entries[index]))
                app.pendingRigAssets.push_back(index);
        for(std::size_t index=0;index<app.assetCatalog.entries.size();++index){
            const auto& candidate=app.assetCatalog.entries[index];
            if(lowerText(selectedWeapon.game)=="aw"&&candidate.role==assets::Role::ViewWeapon&&shouldAutoLoadRigPart(app,selectedWeapon,candidate)){app.pendingRigAssets.push_back(index);continue;}
            if(candidate.game==selectedWeapon.game&&lowerText(candidate.name).find("t6_wpn_knife_base_view")!=std::string::npos){
                app.pendingRigAssets.push_back(index);break;
            }
        }
        logLoading(app, "Identified " + std::to_string(app.pendingRigAssets.size()) + " composite rig components", 0.30f);
        app.loadingActive=true;app.loadingProgress=0.30f;app.loadingLabel="Loading View Weapon";app.loadingDetail=selectedWeapon.name;app.pendingModelStage=1;return;
    }
    if(app.pendingRigCursor<app.pendingRigAssets.size()){
        const auto index=app.pendingRigAssets[app.pendingRigCursor];
        logLoading(app, "Mounting rig mesh: " + app.assetCatalog.entries[index].name, 0.30f + 0.50f * static_cast<float>(app.pendingRigCursor + 1) / std::max<std::size_t>(1,app.pendingRigAssets.size()));
        addRigModelFile(app,app.assetCatalog.entries[index].path,false);
        app.equippedRigAssets.push_back(index);
        ++app.pendingRigCursor;
        app.loadingActive=true;app.loadingDetail=app.assetCatalog.entries[index].name;
        return;
    }
    logLoading(app, "Merging composite rig hierarchy and resolving weapon animations...", 0.85f);
    app.loadingDetail="Finalizing composite rig";app.loadingProgress=0.90f;
    ensureColdWarAnimationSources(app,app.assetCatalog.entries[weaponIndex]);
    finishRigMerge(app,&app.assetCatalog.entries[weaponIndex]);
    const auto& selectedWeapon=app.assetCatalog.entries[weaponIndex];
    if(const auto game=lowerText(selectedWeapon.game);game=="cs2"||game=="bocw_sp"||game=="bocw"||game=="t9"){
        populateDefaultDiscoveredAnimations(app,app.weaponProfile,selectedWeapon);
        app.weaponTiming=app.weaponProfile.stats;
    }
    if(!selectedWeapon.customManifest.empty()){
        std::string error;
        if(!applyCustomContentPackage(app,selectedWeapon.customManifest,error))
            app.status="Custom gun load failed: "+error;
        else if(!error.empty())
            app.status=error;
    }
    selectViewmodelIdle(app,selectedWeapon);
    logLoading(app, "View weapon ready! Indexed " + std::to_string(app.scene.animations.size()) + " animation clips.", 1.0f);
    app.loadingProgress=1.0f;
    app.loadingActive=false;
    app.loadingVisibleUntil=glfwGetTime()+1.0;
    app.pendingModelKind=app.pendingModelStage=0;
    app.pendingViewWeapon=static_cast<std::size_t>(-1);
    app.pendingRigAssets.clear();
    app.pendingRigCursor=0;
}

