void applyWeaponRigState(AppState& app);

void captureWeaponRigState(AppState& app){
    std::set<std::string> assigned;for(const auto& [key,value]:app.weaponProfile.animations)if(!value.empty())assigned.insert(value);
    for(const auto& [key,values]:app.weaponProfile.animationVariants)for(const auto& value:values)assigned.insert(value);
    std::erase_if(app.weaponProfile.animationFiles,[&](const auto& entry){return !assigned.contains(entry.first);});
    for(const auto& name:assigned)for(const auto& path:app.animationSources)if(path.filename().string()==name){app.weaponProfile.animationFiles[name]=path.string();break;}
    auto& profile=app.weaponProfile;profile.baseModel=app.loadedBaseModelPath.string();profile.rigModels.clear();for(const auto& path:app.loadedRigModelPaths)profile.rigModels.push_back(path.string());profile.rigMounts.clear();for(const auto& part:app.scene.rigParts)for(const auto root:part.rootBones)if(root<app.scene.skeleton.bones.size()){const auto& bone=app.scene.skeleton.bones[root];weapon::RigMount mount;mount.model=part.name;mount.rootBone=bone.name;mount.parentTag=bone.parent>=0&&static_cast<std::size_t>(bone.parent)<app.scene.skeleton.bones.size()?app.scene.skeleton.bones[static_cast<std::size_t>(bone.parent)].name:"<root>";mount.position=bone.restLocal.position;mount.rotation=bone.restLocal.rotation;for(const auto& att:app.scene.attachments){if(lowerText(mount.model)==lowerText(att.name)){mount.hasCustomCamoLuma=att.customCamoLuma;mount.materials.useBaseColorLumaMask=att.useBaseColorLumaMask;mount.materials.invertCamoMask=att.invertCamoMask;mount.materials.camoLumaLow=att.camoLumaLow;mount.materials.camoLumaHigh=att.camoLumaHigh;mount.materials.camoLumaGamma=att.camoLumaGamma;mount.materials.camoLumaContrast=att.camoLumaContrast;break;}}profile.rigMounts.push_back(std::move(mount));}
    for(const auto& att:app.scene.attachments){
        weapon::RigMount mount;mount.attachedModel=true;mount.model=att.name;
        mount.parentTag=att.boneIndex<app.scene.skeleton.bones.size()?app.scene.skeleton.bones[att.boneIndex].name:"";
        mount.position=att.position;mount.attachmentRotationDegrees=att.rotationDegrees;mount.attachmentScale=att.scale;
        mount.hasCustomCamoLuma=att.customCamoLuma;mount.materials.useBaseColorLumaMask=att.useBaseColorLumaMask;
        mount.materials.invertCamoMask=att.invertCamoMask;mount.materials.camoLumaLow=att.camoLumaLow;
        mount.materials.camoLumaHigh=att.camoLumaHigh;mount.materials.camoLumaGamma=att.camoLumaGamma;mount.materials.camoLumaContrast=att.camoLumaContrast;
        profile.rigMounts.push_back(std::move(mount));
    }
    profile.hiddenTags.clear();for(const auto index:app.scene.hiddenBones)if(index<app.scene.skeleton.bones.size())profile.hiddenTags.push_back(app.scene.skeleton.bones[index].name);profile.materials.useBaseColorLumaMask=app.camoLumaMask;profile.materials.invertCamoMask=app.camoInvert;profile.materials.camoAlphaLow=app.camoAlphaLow;profile.materials.camoAlphaHigh=app.camoAlphaHigh;profile.materials.camoLumaLow=app.camoLumaLow;profile.materials.camoLumaHigh=app.camoLumaHigh;profile.materials.camoLumaGamma=app.camoLumaGamma;profile.materials.camoLumaContrast=app.camoLumaContrast;profile.materials.specularMultiplier=app.weaponSpecularMultiplier;profile.materials.specularColorLow=app.weaponSpecularLow;profile.materials.specularColorHigh=app.weaponSpecularHigh;app.weaponProfileDirty=true;
}

void autoSaveWeaponProfile(AppState& app){
    captureWeaponRigState(app);
    app.weaponProfile.stats=app.weaponTiming;
    app.weaponProfile.animationPrefix=app.viewmodelAnimationPrefix;
    const auto activeAsset=activeWeaponAssetIndex(app);
    std::filesystem::path targetPath=app.weaponProfilePath;
    if(targetPath.empty()&&activeAsset<app.assetCatalog.entries.size()){
        targetPath=weaponDefaultProfilePath(app.assetCatalog.entries[activeAsset]);
    }
    if(!targetPath.empty()){
        std::error_code ec;
        std::filesystem::create_directories(targetPath.parent_path(),ec);
        std::string err;
        if(weapon::save(app.weaponProfile,targetPath,err)){
            if(activeAsset<app.assetCatalog.entries.size()){
                if(const auto base=coldWarBaseWeaponAsset(app,app.assetCatalog.entries[activeAsset])){
                    const auto basePath=weaponDefaultProfilePath(*base);
                    if(basePath!=targetPath){
                        auto plate=weapon::makeGenerated(base->name,weapon::inferArchetype(base->name),animationPrefixForWeapon(*base));
                        if(std::filesystem::is_regular_file(basePath)&&!weapon::load(basePath,plate,err)){app.status="Saved variant, but base profile could not be read: "+err;return;}
                        weapon::applyFamilyBehavior(plate,app.weaponProfile);
                        std::filesystem::create_directories(basePath.parent_path(),ec);
                        if(ec||!weapon::save(plate,basePath,err)){app.status="Saved variant, but base profile save failed: "+(ec?ec.message():err);return;}
                    }
                }
                const auto familyPath=weaponFamilyProfilePath(app.assetCatalog.entries[activeAsset]);
                if(!familyPath.empty()){
                    std::filesystem::create_directories(familyPath.parent_path(),ec);
                    if(ec||!weapon::save(app.weaponProfile,familyPath,err)){app.status="Saved variant, but family save failed: "+(ec?ec.message():err);return;}
                    for(auto& cached:app.classSlotRigs)if(cached&&cached->weaponAsset<app.assetCatalog.entries.size()&&weaponFamilyProfilePath(app.assetCatalog.entries[cached->weaponAsset])==familyPath)weapon::applyFamilyBehavior(cached->profile,app.weaponProfile);
                }
            }
            app.weaponProfilePath=targetPath;
            app.weaponProfileDirty=false;
            app.status="Saved weapon settings and animation selections to weapfile "+targetPath.filename().string();
        }
        else app.status="Weaponfile save failed: "+err;
    }
}

bool saveCustomContentPackage(AppState& app,bool gun,std::string displayName,std::string& error){
    displayName=displayName.empty()?(gun?app.weaponProfile.name:"Custom player"):displayName;
    const auto id=safePackageId(displayName);
    const auto folder=customContentDirectory()/(gun?"custom_guns":"custom_players")/id;
    const auto assetFolder=folder/"assets";
    std::error_code ec;std::filesystem::create_directories(assetFolder,ec);if(ec){error="Could not create package folder: "+ec.message();return false;}
    std::string originGame;if(app.selectedWeaponAsset<app.assetCatalog.entries.size())originGame=app.assetCatalog.entries[app.selectedWeaponAsset].game;
    if(originGame=="Custom Guns"&&!app.assetCatalog.entries[app.selectedWeaponAsset].customManifest.empty()){CustomContentPackage existing;std::string ignored;if(loadCustomContentManifest(app.assetCatalog.entries[app.selectedWeaponAsset].customManifest,existing,ignored))originGame=existing.originGame;}
    std::filesystem::path weaponModel;
    if(gun){if(app.selectedWeaponAsset>=app.assetCatalog.entries.size()){error="No selected weapon to package";return false;}weaponModel=app.assetCatalog.entries[app.selectedWeaponAsset].path;captureWeaponRigState(app);app.weaponProfile.stats=app.weaponTiming;app.weaponProfile.animationPrefix=app.viewmodelAnimationPrefix;app.weaponProfile.name=displayName;if(!weapon::save(app.weaponProfile,folder/"weapon.iwweapon",error))return false;}
    if(app.loadedBaseModelPath.empty()||!std::filesystem::is_regular_file(app.loadedBaseModelPath)){error="The current base viewhands/player model is missing";return false;}
    std::ofstream out(folder/"manifest.cadenceasset",std::ios::trunc);if(!out){error="Could not create package manifest";return false;}
    out<<"CADENCECUSTOM 1\n"<<"type "<<(gun?"gun":"player")<<'\n'<<"id "<<std::quoted(id)<<'\n'<<"name "<<std::quoted(displayName)<<'\n'<<"origin_game "<<std::quoted(originGame)<<'\n'<<"base_model "<<std::quoted(app.loadedBaseModelPath.string())<<'\n';
    if(gun)out<<"weapon_model "<<std::quoted(weaponModel.string())<<'\n'<<"profile "<<std::quoted("weapon.iwweapon")<<'\n';
    out<<"dependency "<<std::quoted(app.loadedBaseModelPath.string())<<'\n';if(gun){out<<"dependency "<<std::quoted(weaponModel.string())<<'\n';for(const auto& path:app.loadedRigModelPaths)out<<"dependency "<<std::quoted(path.string())<<'\n';}
    const auto count=std::min(app.loadedAttachmentPaths.size(),app.scene.attachments.size());std::unordered_set<std::string> copiedNames;
    for(std::size_t i=0;i<count;++i){auto stored=app.loadedAttachmentPaths[i];if(lowerText(stored.extension().string())==".glb"){auto filename=stored.filename();for(int suffix=2;copiedNames.contains(lowerText(filename.string()));++suffix)filename=stored.stem().string()+"_"+std::to_string(suffix)+stored.extension().string();copiedNames.insert(lowerText(filename.string()));const auto destination=assetFolder/filename;std::filesystem::copy_file(stored,destination,std::filesystem::copy_options::overwrite_existing,ec);if(!ec)stored=std::filesystem::path("assets")/filename;ec.clear();}else out<<"dependency "<<std::quoted(stored.string())<<'\n';const auto& attachment=app.scene.attachments[i];const auto bone=attachment.boneIndex<app.scene.skeleton.bones.size()?app.scene.skeleton.bones[attachment.boneIndex].name:std::string{};out<<"attachment "<<std::quoted(stored.generic_string())<<' '<<std::quoted(bone)<<' '<<attachment.position.x<<' '<<attachment.position.y<<' '<<attachment.position.z<<' '<<attachment.rotationDegrees.x<<' '<<attachment.rotationDegrees.y<<' '<<attachment.rotationDegrees.z<<' '<<attachment.scale.x<<' '<<attachment.scale.y<<' '<<attachment.scale.z<<'\n';}
    out.close();if(!out){error="Could not finish package manifest";return false;}refreshCustomContentCatalog(app);error.clear();return true;
}

void drawCustomContent(AppState& app){static bool wasOpen=false;const bool open=ImGui::CollapsingHeader("Portable Custom Content");const bool justOpened=open&&!wasOpen;wasOpen=open;if(!open)return;uiHelp("Packages live beside Cadence, appear as Custom Guns or Custom Players, list required ripped content, and embed custom GLB attachments.");ImGui::InputText("Package name",app.customContentName.data(),app.customContentName.size());if(ImGui::Button("Save current gun")){std::string error;if(saveCustomContentPackage(app,true,app.customContentName.data(),error))app.status="Saved custom gun package";else app.status=error;}ImGui::SameLine();if(ImGui::Button("Save current player")){std::string error;if(saveCustomContentPackage(app,false,app.customContentName.data(),error))app.status="Saved custom player package";else app.status=error;}ImGui::SameLine();if(ImGui::Button("Refresh packages")){refreshCustomContentCatalog(app);app.status="Refreshed portable custom content";}const auto packages=customContentPackages(justOpened);for(const auto& package:*packages){ImGui::PushID(package.manifest.string().c_str());if(ImGui::TreeNode((package.name+"  ["+package.type+"]").c_str())){std::size_t missing{};for(const auto& dependency:package.dependencies)if(!std::filesystem::is_regular_file(packagePath(package,dependency)))++missing;ImGui::Text("Origin: %s",package.originGame.empty()?"Custom":package.originGame.c_str());ImGui::TextColored(missing?ImVec4(1,.45f,.25f,1):ImVec4(.4f,1,.55f,1),missing?"Missing dependencies: %zu":"All %zu dependencies available",missing?missing:package.dependencies.size());if(ImGui::Button("Load package now")){if(package.type=="player"){loadFile(app,packagePath(package,package.baseModel));std::string error;if(!applyCustomContentPackage(app,package.manifest,error))app.status=error;else app.status=error.empty()?"Loaded custom player "+package.name:error;}else{refreshCustomContentCatalog(app);for(std::size_t i=0;i<app.assetCatalog.entries.size();++i)if(app.assetCatalog.entries[i].role==assets::Role::ViewWeapon&&app.assetCatalog.entries[i].customPackageId==package.id){app.selectedWeaponAsset=i;app.selectedBaseAsset=classHandsForWeapon(app,app.assetCatalog.entries[i]);queueViewWeaponLoad(app,i);break;}}}ImGui::TreePop();}ImGui::PopID();}}

bool rebuildWeaponProfileRig(AppState& app){
    const auto base=std::filesystem::u8path(app.weaponProfile.baseModel);if(app.weaponProfile.baseModel.empty()||!std::filesystem::is_regular_file(base))return false;const auto profile=app.weaponProfile;const auto path=app.weaponProfilePath;const auto sources=app.animationSources;auto documents=std::move(app.animationDocuments);loadFile(app,base);app.animationSources=sources;app.animationDocuments=std::move(documents);for(const auto& modelText:profile.rigModels){const auto model=std::filesystem::u8path(modelText);if(std::filesystem::is_regular_file(model))addRigModelFile(app,model,false);}finishRigMerge(app);activateWeaponProfile(app,profile,path);applyWeaponRigState(app);if(const auto idle=findViewmodelClip(app,"idle")){app.animationIndex=app.previousAnimationIndex=*idle;app.animationFrame=app.previousAnimationFrame=0;}return true;
}

void applyWeaponRigState(AppState& app){
    for(auto& att:app.scene.attachments)for(const auto& mount:app.weaponProfile.rigMounts)if(mount.attachedModel&&lowerText(mount.model)==lowerText(att.name)){
        att.position=mount.position;att.rotationDegrees=mount.attachmentRotationDegrees;att.scale=mount.attachmentScale;
        if(const auto bone=app.scene.skeleton.boneByName.find(mount.parentTag);bone!=app.scene.skeleton.boneByName.end())att.boneIndex=bone->second;
        break;
    }
    for(const auto& mount:app.weaponProfile.rigMounts)if(!mount.attachedModel)for(const auto& part:app.scene.rigParts)if(lowerText(part.name)==lowerText(mount.model))for(const auto root:part.rootBones)if(root<app.scene.skeleton.bones.size()&&lowerText(app.scene.skeleton.bones[root].name)==lowerText(mount.rootBone)){app.scene.rigMountReferences.try_emplace(root,app.scene.skeleton.bones[root].restLocal);app.scene.skeleton.bones[root].restLocal.position=mount.position;app.scene.skeleton.bones[root].restLocal.rotation=mount.rotation;}
    for(std::size_t i=0;i<app.scene.attachments.size();++i){auto& att=app.scene.attachments[i];for(const auto& mount:app.weaponProfile.rigMounts){if(lowerText(mount.model)==lowerText(att.name)&&mount.hasCustomCamoLuma){att.customCamoLuma=true;att.useBaseColorLumaMask=mount.materials.useBaseColorLumaMask;att.invertCamoMask=mount.materials.invertCamoMask;att.camoLumaLow=mount.materials.camoLumaLow;att.camoLumaHigh=mount.materials.camoLumaHigh;att.camoLumaGamma=mount.materials.camoLumaGamma;att.camoLumaContrast=mount.materials.camoLumaContrast;app.renderer.setAttachmentCamoLuma(static_cast<int>(i),att.useBaseColorLumaMask,att.invertCamoMask,att.camoLumaLow,att.camoLumaHigh,att.camoLumaGamma,att.camoLumaContrast);break;}}}
    app.scene.hiddenBones.clear();for(const auto& tag:app.weaponProfile.hiddenTags){const auto found=app.scene.skeleton.boneByName.find(tag);if(found!=app.scene.skeleton.boneByName.end())app.scene.hiddenBones.insert(found->second);else if(const auto canonical=app.scene.skeleton.boneByCanonicalName.find(lowerText(tag));canonical!=app.scene.skeleton.boneByCanonicalName.end())app.scene.hiddenBones.insert(canonical->second);}if(app.meleeKnifeBone<app.scene.skeleton.bones.size())app.scene.hiddenBones.insert(app.meleeKnifeBone);
}

