void applyThemeColorsToCampath(AppState& app){
    const auto& style=ImGui::GetStyle();
    const ImVec4 accent=style.Colors[ImGuiCol_HeaderActive];
    const ImVec4 active=style.Colors[ImGuiCol_ButtonActive];
    const ImVec4 nav=style.Colors[ImGuiCol_NavHighlight];
    const ImVec4 tab=style.Colors[ImGuiCol_TabActive];
    app.campathSplineColor={accent.x,accent.y,accent.z};
    app.campathNodeColor={nav.x>0.05f?nav.x:(active.x>0.05f?active.x:1.0f),nav.y>0.05f?nav.y:(active.y>0.05f?active.y:0.8f),nav.z>0.05f?nav.z:(active.z>0.05f?active.z:0.2f)};
    app.campathFrustumColor={tab.x>0.05f?tab.x:0.25f,tab.y>0.05f?tab.y:0.95f,tab.z>0.05f?tab.z:0.65f};
}

void drawIWXMVMVisualTimeline(AppState& app,float width,float height){
    const float duration=app.recordedTake.duration();
    if(duration<=0.0001f){
        ImGui::TextDisabled("Record or load a take first.");
        return;
    }
    const float sampleRate=std::max(1.0f,app.recordedTake.sampleRate);
    const float totalTicks=duration*sampleRate;
    ImGui::PushStyleColor(ImGuiCol_ChildBg,ImVec4(0.025f,0.032f,0.045f,0.98f));
    if(ImGui::BeginChild("iwxmvm_timeline_widget",ImVec2(width,height),ImGuiChildFlags_Borders,ImGuiWindowFlags_NoScrollbar|ImGuiWindowFlags_NoScrollWithMouse)){
        auto* drawList=ImGui::GetWindowDrawList();
        const ImVec2 canvasMin=ImGui::GetCursorScreenPos();
        const ImVec2 canvasSize=ImGui::GetContentRegionAvail();
        const ImVec2 canvasMax=ImVec2(canvasMin.x+canvasSize.x,canvasMin.y+canvasSize.y);
        const float padX=14.0f;
        const float rulerLeft=canvasMin.x+padX;
        const float rulerRight=canvasMax.x-padX;
        const float rulerWidth=std::max(10.0f,rulerRight-rulerLeft);
        const float rulerTop=canvasMin.y+3.0f;
        const float rulerBottom=canvasMin.y+22.0f;
        const float trackTop=rulerBottom+2.0f;
        const float trackBottom=canvasMax.y-4.0f;

        drawList->AddRectFilled(canvasMin,canvasMax,IM_COL32(10,14,20,255));
        drawList->AddRectFilled({rulerLeft,rulerTop},{rulerRight,rulerBottom},IM_COL32(18,24,34,255),2.0f);
        drawList->AddRectFilled({rulerLeft,trackTop},{rulerRight,trackBottom},IM_COL32(14,18,26,255),2.0f);

        const float startTrimX=rulerLeft+(std::clamp(app.exportStart/duration,0.0f,1.0f))*rulerWidth;
        const float endTrimX=rulerLeft+(std::clamp(app.exportEnd/duration,0.0f,1.0f))*rulerWidth;
        if(app.exportStart>0.0f)drawList->AddRectFilled({rulerLeft,trackTop},{startTrimX,trackBottom},IM_COL32(40,20,20,160));
        if(app.exportEnd<duration)drawList->AddRectFilled({endTrimX,trackTop},{rulerRight,trackBottom},IM_COL32(40,20,20,160));
        drawList->AddLine({startTrimX,rulerTop},{startTrimX,trackBottom},IM_COL32(60,255,100,240),2.0f);
        drawList->AddLine({endTrimX,rulerTop},{endTrimX,trackBottom},IM_COL32(255,75,75,240),2.0f);
        drawList->AddTriangleFilled({startTrimX,trackTop},{startTrimX+7,trackTop},{startTrimX,trackTop+8},IM_COL32(60,255,100,255));
        drawList->AddTriangleFilled({endTrimX,trackTop},{endTrimX-7,trackTop},{endTrimX,trackTop+8},IM_COL32(255,75,75,255));
        drawList->AddText({std::min(startTrimX+4,rulerRight-40),trackBottom-15},IM_COL32(60,255,100,255),"START");
        drawList->AddText({std::max(rulerLeft,endTrimX-29),trackBottom-30},IM_COL32(255,75,75,255),"END");

        float majorInterval=1.0f;
        if(duration>30.0f)majorInterval=5.0f;
        else if(duration>15.0f)majorInterval=2.0f;
        else if(duration<3.0f)majorInterval=0.5f;

        for(float t=0.0f;t<=duration+0.001f;t+=majorInterval*0.2f){
            const float frac=t/duration;
            const float x=rulerLeft+frac*rulerWidth;
            const bool isMajor=std::fmod(t+0.0001f,majorInterval)<0.05f||t<0.001f;
            const float tickHeight=isMajor?12.0f:6.0f;
            drawList->AddLine({x,rulerBottom-tickHeight},{x,rulerBottom},isMajor?IM_COL32(200,215,230,220):IM_COL32(100,120,140,160),1.0f);
            if(isMajor&&x+35.0f<canvasMax.x){
                char label[32]{};
                std::snprintf(label,sizeof(label),"%.1fs (%d)",t,static_cast<int>(std::round(t*sampleRate)));
                drawList->AddText({x+3.0f,rulerTop+1.0f},IM_COL32(180,200,220,220),label);
            }
        }

        const auto& keys=app.recordedTake.dollyCamera;
        int hoveredNode=-1;
        const auto mousePos=ImGui::GetMousePos();
        for(std::size_t i=0;i<keys.size();++i){
            const auto& node=keys[i];
            const float nodeTime=static_cast<float>(node.tick)/sampleRate;
            const float nodeX=rulerLeft+std::clamp(nodeTime/duration,0.0f,1.0f)*rulerWidth;
            const float nodeY=(trackTop+trackBottom)*0.5f;
            const bool selected=(static_cast<int>(i)==app.selectedCampathNode);
            const float sz=selected?7.0f:5.5f;
            const ImU32 fillCol=selected?IM_COL32(255,240,100,255):IM_COL32(0,215,255,230);
            const ImU32 borderCol=IM_COL32(255,255,255,255);
            const ImVec2 p[4]={{nodeX,nodeY-sz},{nodeX+sz,nodeY},{nodeX,nodeY+sz},{nodeX-sz,nodeY}};
            drawList->AddQuadFilled(p[0],p[1],p[2],p[3],fillCol);
            drawList->AddQuad(p[0],p[1],p[2],p[3],borderCol,1.5f);
            drawList->AddLine({nodeX,trackTop-2.0f},{nodeX,trackTop},IM_COL32(0,215,255,120),1.0f);

            if(mousePos.y>=trackTop-2.0f&&mousePos.y<=trackBottom&&std::abs(mousePos.x-nodeX)<=6.0f){
                hoveredNode=static_cast<int>(i);
                drawList->AddCircle({nodeX,nodeY},sz+3.0f,IM_COL32(255,255,255,200),12,1.2f);
            }
        }

        // Decoded Notetrack Events on timeline ruler
        if(app.animationIndex<app.scene.animations.size()){
            const auto& activeClip=app.scene.animations[app.animationIndex];
            const float clipFps=std::max(1.0f,activeClip.framerate);
            for(const auto& notif:activeClip.notifications){
                ImU32 notifCol=IM_COL32(200,200,220,230);
                switch(notif.kind){
                    case scene::NotetrackKind::Fire:
                    case scene::NotetrackKind::MuzzleFlash:
                        notifCol=IM_COL32(255,140,30,240); break;
                    case scene::NotetrackKind::EjectBrass:
                    case scene::NotetrackKind::DropClip:
                    case scene::NotetrackKind::ClipIn:
                        notifCol=IM_COL32(0,220,255,240); break;
                    case scene::NotetrackKind::Rechamber:
                        notifCol=IM_COL32(80,240,120,240); break;
                    case scene::NotetrackKind::Sound:
                    case scene::NotetrackKind::Footstep:
                        notifCol=IM_COL32(255,230,80,240); break;
                    default: break;
                }
                for(const auto frame:notif.frames){
                    const float notifTime=static_cast<float>(frame)/clipFps;
                    const float notifFrac=std::clamp(notifTime/duration,0.0f,1.0f);
                    const float notifX=rulerLeft+notifFrac*rulerWidth;
                    drawList->AddLine({notifX,trackTop},{notifX,trackBottom},notifCol,1.0f);
                    drawList->AddCircleFilled({notifX,trackTop+3.0f},2.5f,notifCol);
                    if(mousePos.y>=trackTop&&mousePos.y<=trackBottom&&std::abs(mousePos.x-notifX)<=4.0f){
                        uiHelp("Notetrack: %s\nCategory: %s\nFrame: %u (%.2fs)",notif.name.c_str(),scene::notetrackKindName(notif.kind),frame,notifTime);
                    }
                }
            }
        }

        const float playheadFrac=std::clamp(app.takeTime/duration,0.0f,1.0f);
        const float playheadX=rulerLeft+playheadFrac*rulerWidth;
        drawList->AddLine({playheadX,rulerTop},{playheadX,trackBottom},IM_COL32(255,60,60,255),2.0f);
        const ImVec2 headP[3]={{playheadX-6.0f,rulerTop},{playheadX+6.0f,rulerTop},{playheadX,rulerTop+8.0f}};
        drawList->AddTriangleFilled(headP[0],headP[1],headP[2],IM_COL32(255,80,80,255));

        ImGui::SetCursorScreenPos(canvasMin);
        ImGui::InvisibleButton("##iwxmvm_timeline_interact",canvasSize);
        const bool isHovered=ImGui::IsItemHovered();
        const bool isClicked=ImGui::IsItemClicked(ImGuiMouseButton_Left);
        const bool isDoubleClicked=ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left);

        if(isDoubleClicked&&isHovered){
            placeDollyNode(app);
        }else if(isClicked){
            if(mousePos.y<=rulerBottom){
                // Ruler area: ALWAYS scrub playhead
                app.timelineDraggingNode=false;
                app.timelineDraggedNodeIndex=-1;
                const float newFrac=std::clamp((mousePos.x-rulerLeft)/rulerWidth,0.0f,1.0f);
                app.takeTime=newFrac*duration;
                app.takePlaying=false;
                app.takePreview=true;
            }else{
                // Track area: grab node only if directly clicking a node diamond
                if(hoveredNode>=0){
                    app.selectedCampathNode=hoveredNode;
                    app.timelineDraggingNode=true;
                    app.timelineDraggedNodeIndex=hoveredNode;
                }else{
                    app.timelineDraggingNode=false;
                    app.timelineDraggedNodeIndex=-1;
                    const float newFrac=std::clamp((mousePos.x-rulerLeft)/rulerWidth,0.0f,1.0f);
                    app.takeTime=newFrac*duration;
                    app.takePlaying=false;
                    app.takePreview=true;
                }
            }
        }

        if(app.timelineDraggingNode&&ImGui::IsMouseDown(ImGuiMouseButton_Left)){
            if(app.timelineDraggedNodeIndex>=0&&app.timelineDraggedNodeIndex<static_cast<int>(app.recordedTake.dollyCamera.size())){
                const float newFrac=std::clamp((mousePos.x-rulerLeft)/rulerWidth,0.0f,1.0f);
                const float newTime=newFrac*duration;
                const std::uint32_t newTick=static_cast<std::uint32_t>(std::clamp(std::round(newTime*sampleRate),0.0f,totalTicks));
                app.recordedTake.dollyCamera[app.timelineDraggedNodeIndex].tick=newTick;
                std::sort(app.recordedTake.dollyCamera.begin(),app.recordedTake.dollyCamera.end(),[](const auto& a,const auto& b){return a.tick<b.tick;});
                for(std::size_t i=0;i<app.recordedTake.dollyCamera.size();++i){
                    if(app.recordedTake.dollyCamera[i].tick==newTick){
                        app.selectedCampathNode=static_cast<int>(i);
                        app.timelineDraggedNodeIndex=static_cast<int>(i);
                        break;
                    }
                }
                app.takeTime=static_cast<float>(newTick)/sampleRate;
                app.takePlaying=false;
                app.takePreview=true;
            }
        }else if(!ImGui::IsMouseDown(ImGuiMouseButton_Left)){
            app.timelineDraggingNode=false;
            app.timelineDraggedNodeIndex=-1;
        }else if(ImGui::IsItemActive()&&!app.timelineDraggingNode){
            const float newFrac=std::clamp((mousePos.x-rulerLeft)/rulerWidth,0.0f,1.0f);
            app.takeTime=newFrac*duration;
            app.takePlaying=false;
            app.takePreview=true;
        }

        if(hoveredNode>=0&&hoveredNode<static_cast<int>(keys.size())){
            const auto& node=keys[hoveredNode];
            ImGui::BeginTooltip();
            ImGui::Text("Node #%d  ·  Tick %u (%.3fs)",hoveredNode+1,node.tick,static_cast<float>(node.tick)/sampleRate);
            ImGui::Text("Pos:  %.1f, %.1f, %.1f",node.position.x,node.position.y,node.position.z);
            ImGui::Text("Rot:  P %.1f  Y %.1f  R %.1f",node.rotationDegrees.x,node.rotationDegrees.y,node.rotationDegrees.z);
            ImGui::Text("FOV:  %.1f deg",node.fov);
            uiHelp("Click node to drag timestamp · Click top ruler to scrub playhead");
            ImGui::EndTooltip();
        }
    }
    ImGui::EndChild();
    ImGui::PopStyleColor();
    ImGui::PushID("recording_range");
    ImGui::BeginDisabled(app.exportActive||app.takeRecording);
    if(ImGui::Button("Set recording start"))cadence::replay::setCaptureBoundary(app.takeTime,duration,sampleRate,true,app.exportStart,app.exportEnd);
    if(ImGui::GetContentRegionAvail().x>ImGui::CalcTextSize("Set recording end").x+35.f)ImGui::SameLine();
    if(ImGui::Button("Set recording end"))cadence::replay::setCaptureBoundary(app.takeTime,duration,sampleRate,false,app.exportStart,app.exportEnd);
    ImGui::EndDisabled();
    ImGui::Text("Tick %llu / %llu | Start %llu | End %llu",
        static_cast<unsigned long long>(cadence::replay::tickAt(app.takeTime,duration,sampleRate)),
        static_cast<unsigned long long>(cadence::replay::tickAt(duration,duration,sampleRate)),
        static_cast<unsigned long long>(cadence::replay::tickAt(app.exportStart,duration,sampleRate)),
        static_cast<unsigned long long>(cadence::replay::tickAt(app.exportEnd,duration,sampleRate)));
    ImGui::PopID();
}

void drawIWXMVMGraphEditor(AppState& app,float width,float height){
    const float duration=app.recordedTake.duration();
    if(duration<=0.0001f){
        ImGui::TextDisabled("Record or load a take to inspect camera curves.");
        return;
    }
    const float sampleRate=std::max(1.0f,app.recordedTake.sampleRate);
    auto& keys=app.recordedTake.dollyCamera;

    ImGui::PushID("graph_splitter_id");
    const ImVec2 splitterScreenPos=ImGui::GetCursorScreenPos();
    ImGui::InvisibleButton("##graph_splitter_handle",ImVec2(width>0?width:ImGui::GetContentRegionAvail().x,6.0f));
    const bool splitterHovered=ImGui::IsItemHovered();
    if(splitterHovered||app.graphEditorResizing)ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeNS);
    if(ImGui::IsItemActive())app.graphEditorResizing=true;
    if(app.graphEditorResizing){
        if(ImGui::IsMouseDown(ImGuiMouseButton_Left))app.graphEditorHeight=std::clamp(app.graphEditorHeight-ImGui::GetIO().MouseDelta.y,90.0f,600.0f);
        else app.graphEditorResizing=false;
    }
    auto* winDraw=ImGui::GetWindowDrawList();
    const float actualWidth=width>0?width:ImGui::GetContentRegionAvail().x;
    winDraw->AddRectFilled(splitterScreenPos,ImVec2(splitterScreenPos.x+actualWidth,splitterScreenPos.y+4.0f),
                           app.graphEditorResizing?IM_COL32(0,200,255,255):(splitterHovered?IM_COL32(0,160,220,200):IM_COL32(40,50,68,200)));
    ImGui::PopID();

    ImGui::PushStyleColor(ImGuiCol_ChildBg,ImVec4(0.02f,0.025f,0.035f,0.98f));
    if(ImGui::BeginChild("iwxmvm_graph_editor_child",ImVec2(width,app.graphEditorHeight),ImGuiChildFlags_Borders,ImGuiWindowFlags_NoScrollbar|ImGuiWindowFlags_NoScrollWithMouse)){
        ImGui::PushStyleVar(ImGuiStyleVar_FramePadding,ImVec2(4,2));
        ImGui::PushStyleColor(ImGuiCol_Text,ImVec4(1.0f,0.35f,0.35f,1.0f));ImGui::Checkbox("X##gx",&app.graphShowPosX);ImGui::PopStyleColor();ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Text,ImVec4(0.35f,1.0f,0.35f,1.0f));ImGui::Checkbox("Y##gy",&app.graphShowPosY);ImGui::PopStyleColor();ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Text,ImVec4(0.35f,0.65f,1.0f,1.0f));ImGui::Checkbox("Z##gz",&app.graphShowPosZ);ImGui::PopStyleColor();ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Text,ImVec4(1.0f,0.70f,0.20f,1.0f));ImGui::Checkbox("Pitch##gp",&app.graphShowPitch);ImGui::PopStyleColor();ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Text,ImVec4(1.0f,1.0f,0.25f,1.0f));ImGui::Checkbox("Yaw##gyw",&app.graphShowYaw);ImGui::PopStyleColor();ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Text,ImVec4(0.25f,1.0f,1.0f,1.0f));ImGui::Checkbox("Roll##gr",&app.graphShowRoll);ImGui::PopStyleColor();ImGui::SameLine();
        ImGui::PushStyleColor(ImGuiCol_Text,ImVec4(1.0f,0.35f,1.0f,1.0f));ImGui::Checkbox("FOV##gf",&app.graphShowFov);ImGui::PopStyleColor();ImGui::SameLine();
        ImGui::Checkbox("Bezier Handles##gbz",&app.graphShowBezierHandles);ImGui::SameLine();
        if(ImGui::SmallButton("Fit View##gfit")){app.graphZoomX=app.graphZoomY=1.0f;app.graphPanX=app.graphPanY=0.0f;}ImGui::SameLine();
        if(ImGui::SmallButton("Close##close_graph")){app.showGraphEditor=false;}
        ImGui::PopStyleVar();

        auto* drawList=ImGui::GetWindowDrawList();
        const ImVec2 canvasMin=ImGui::GetCursorScreenPos();
        const ImVec2 canvasSize=ImGui::GetContentRegionAvail();
        const ImVec2 canvasMax=ImVec2(canvasMin.x+canvasSize.x,canvasMin.y+canvasSize.y);

        if(canvasSize.x>20.0f&&canvasSize.y>20.0f){
            const float padL=42.0f,padR=14.0f,padT=6.0f,padB=18.0f;
            const float graphL=canvasMin.x+padL,graphR=canvasMax.x-padR;
            const float graphT=canvasMin.y+padT,graphB=canvasMax.y-padB;
            const float graphW=std::max(10.0f,graphR-graphL);
            const float graphH=std::max(10.0f,graphB-graphT);

            drawList->AddRectFilled(canvasMin,canvasMax,IM_COL32(8,11,16,255));
            drawList->AddRectFilled({graphL,graphT},{graphR,graphB},IM_COL32(12,16,24,255));
            drawList->AddRect({graphL,graphT},{graphR,graphB},IM_COL32(35,45,60,255));

            float baseMinVal=0.0f,baseMaxVal=100.0f;
            bool hasRange=false;
            const auto considerVal=[&](float v){
                if(!hasRange){baseMinVal=baseMaxVal=v;hasRange=true;}
                else{baseMinVal=std::min(baseMinVal,v);baseMaxVal=std::max(baseMaxVal,v);}
            };

            for(const auto& k:keys){
                if(app.graphShowPosX)considerVal(k.position.x);
                if(app.graphShowPosY)considerVal(k.position.y);
                if(app.graphShowPosZ)considerVal(k.position.z);
                if(app.graphShowPitch)considerVal(k.rotationDegrees.x);
                if(app.graphShowYaw)considerVal(k.rotationDegrees.y);
                if(app.graphShowRoll)considerVal(k.rotationDegrees.z);
                if(app.graphShowFov)considerVal(k.fov);
            }
            if(baseMinVal==baseMaxVal){baseMinVal-=10.0f;baseMaxVal+=10.0f;}
            const float basePadding=(baseMaxVal-baseMinVal)*0.08f;
            baseMinVal-=basePadding;baseMaxVal+=basePadding;
            const float baseValSpan=std::max(0.001f,baseMaxVal-baseMinVal);

            // AE zoom/pan calculations
            const float centerT=duration*0.5f-app.graphPanX;
            const float halfDur=(duration*0.5f)/std::clamp(app.graphZoomX,0.05f,50.0f);
            const float viewMinT=centerT-halfDur,viewMaxT=centerT+halfDur;
            const float viewDurSpan=std::max(0.001f,viewMaxT-viewMinT);

            const float centerVal=(baseMinVal+baseMaxVal)*0.5f-app.graphPanY;
            const float halfSpan=(baseValSpan*0.5f)/std::clamp(app.graphZoomY,0.05f,50.0f);
            const float viewMinVal=centerVal-halfSpan,viewMaxVal=centerVal+halfSpan;
            const float viewValSpan=std::max(0.001f,viewMaxVal-viewMinVal);

            const auto timeToX=[&](float t)->float{return graphL+((t-viewMinT)/viewDurSpan)*graphW;};
            const auto xToTime=[&](float x)->float{return viewMinT+((x-graphL)/graphW)*viewDurSpan;};
            const auto valToY=[&](float v)->float{return graphB-((v-viewMinVal)/viewValSpan)*graphH;};
            const auto yToVal=[&](float y)->float{return viewMinVal+((graphB-y)/graphH)*viewValSpan;};

            drawList->PushClipRect({graphL,graphT},{graphR,graphB},true);

            // Grid lines
            for(int step=0;step<=4;++step){
                const float frac=static_cast<float>(step)/4.0f;
                const float y=graphB-frac*graphH;
                const float val=viewMinVal+frac*viewValSpan;
                drawList->AddLine({graphL,y},{graphR,y},IM_COL32(30,38,52,180),1.0f);
                char vlabel[24]{};
                std::snprintf(vlabel,sizeof(vlabel),"%.0f",val);
                drawList->AddText({canvasMin.x+2.0f,y-6.0f},IM_COL32(120,140,160,200),vlabel);
            }

            float timeStep=viewDurSpan>10.0f?2.0f:(viewDurSpan>3.0f?1.0f:0.5f);
            const float firstGridT=std::floor(viewMinT/timeStep)*timeStep;
            for(float t=firstGridT;t<=viewMaxT+timeStep;t+=timeStep){
                const float x=timeToX(t);
                if(x<graphL||x>graphR)continue;
                drawList->AddLine({x,graphT},{x,graphB},IM_COL32(30,38,52,180),1.0f);
                char tlabel[16]{};
                std::snprintf(tlabel,sizeof(tlabel),"%.1fs",t);
                drawList->AddText({x-8.0f,graphB+2.0f},IM_COL32(120,140,160,200),tlabel);
            }

            // Plot curves and keyframe markers
            const auto getChannelVal=[&](const take::DollyCameraKeyframe& k,int ch)->float{
                if(ch==0)return k.position.x;
                if(ch==1)return k.position.y;
                if(ch==2)return k.position.z;
                if(ch==3)return k.rotationDegrees.x;
                if(ch==4)return k.rotationDegrees.y;
                if(ch==5)return k.rotationDegrees.z;
                return k.fov;
            };

            const auto setChannelVal=[&](take::DollyCameraKeyframe& k,int ch,float v){
                if(ch==0)k.position.x=v;
                else if(ch==1)k.position.y=v;
                else if(ch==2)k.position.z=v;
                else if(ch==3)k.rotationDegrees.x=v;
                else if(ch==4)k.rotationDegrees.y=v;
                else if(ch==5)k.rotationDegrees.z=v;
                else if(ch==6)k.fov=std::clamp(v,1.0f,179.0f);
            };

            int clickedNodeIdx=-1,clickedChannelIdx=-1;
            int clickedHandleIdx=-1,clickedHandleNode=-1,clickedHandleChannel=-1;
            const auto mousePos=ImGui::GetMousePos();

            const auto plotChannel=[&](int channelIdx,ImU32 color){
                if(keys.empty())return;
                const int numSamples=std::max(48,static_cast<int>(graphW*0.6f));
                const float tickStep=(duration*sampleRate)/static_cast<float>(numSamples);
                ImVec2 prevPt{};
                for(int s=0;s<=numSamples;++s){
                    const float tick=s*tickStep;
                    const auto smp=take::interpolateDollyCamera(keys,tick);
                    const float val=getChannelVal(smp,channelIdx);
                    const float x=timeToX(tick/sampleRate);
                    const float y=valToY(val);
                    const ImVec2 curPt{x,y};
                    if(s>0)drawList->AddLine(prevPt,curPt,color,1.8f);
                    prevPt=curPt;
                }

                for(std::size_t i=0;i<keys.size();++i){
                    const auto& k=keys[i];
                    const float val=getChannelVal(k,channelIdx);
                    const float x=timeToX(static_cast<float>(k.tick)/sampleRate);
                    const float y=valToY(val);
                    const bool selected=(static_cast<int>(i)==app.selectedCampathNode);

                    // Bezier Tangent handles
                    if(app.graphShowBezierHandles&&selected){
                        float slope=0.0f;
                        if(keys.size()>=2){
                            const std::size_t prevIdx=i>0?i-1:i;
                            const std::size_t nextIdx=i+1<keys.size()?i+1:i;
                            if(prevIdx!=nextIdx){
                                const float dt=static_cast<float>(keys[nextIdx].tick-keys[prevIdx].tick)/sampleRate;
                                if(dt>0.001f)slope=(getChannelVal(keys[nextIdx],channelIdx)-getChannelVal(keys[prevIdx],channelIdx))/dt;
                            }
                        }
                        const float handleDist=32.0f;
                        const ImVec2 hL{x-handleDist,y+(slope/viewValSpan)*handleDist*(graphH/graphW)};
                        const ImVec2 hR{x+handleDist,y-(slope/viewValSpan)*handleDist*(graphH/graphW)};
                        drawList->AddLine({x,y},hL,IM_COL32(200,220,240,180),1.2f);
                        drawList->AddLine({x,y},hR,IM_COL32(200,220,240,180),1.2f);
                        drawList->AddCircleFilled(hL,3.5f,IM_COL32(240,240,100,240));
                        drawList->AddCircleFilled(hR,3.5f,IM_COL32(240,240,100,240));

                        if(std::abs(mousePos.x-hL.x)<=7.0f&&std::abs(mousePos.y-hL.y)<=7.0f){
                            clickedHandleIdx=0;
                            clickedHandleNode=static_cast<int>(i);
                            clickedHandleChannel=channelIdx;
                            drawList->AddCircle(hL,7.5f,IM_COL32(255,255,255,240),12,1.5f);
                        }else if(std::abs(mousePos.x-hR.x)<=7.0f&&std::abs(mousePos.y-hR.y)<=7.0f){
                            clickedHandleIdx=1;
                            clickedHandleNode=static_cast<int>(i);
                            clickedHandleChannel=channelIdx;
                            drawList->AddCircle(hR,7.5f,IM_COL32(255,255,255,240),12,1.5f);
                        }
                    }

                    drawList->AddCircleFilled({x,y},selected?5.5f:4.0f,color);
                    drawList->AddCircle({x,y},selected?6.5f:5.0f,IM_COL32(255,255,255,255),12,1.5f);

                    if(std::abs(mousePos.x-x)<=7.0f&&std::abs(mousePos.y-y)<=7.0f){
                        clickedNodeIdx=static_cast<int>(i);
                        clickedChannelIdx=channelIdx;
                        drawList->AddCircle({x,y},8.0f,IM_COL32(255,255,255,240),12,1.8f);
                    }
                }
            };

            if(app.graphShowPosX)plotChannel(0,IM_COL32(255,80,80,240));
            if(app.graphShowPosY)plotChannel(1,IM_COL32(80,255,80,240));
            if(app.graphShowPosZ)plotChannel(2,IM_COL32(80,160,255,240));
            if(app.graphShowPitch)plotChannel(3,IM_COL32(255,175,50,240));
            if(app.graphShowYaw)plotChannel(4,IM_COL32(255,255,60,240));
            if(app.graphShowRoll)plotChannel(5,IM_COL32(60,255,255,240));
            if(app.graphShowFov)plotChannel(6,IM_COL32(255,80,255,240));

            // Decoded Notetrack Events on Graph
            if(app.animationIndex<app.scene.animations.size()){
                const auto& activeClip=app.scene.animations[app.animationIndex];
                const float clipFps=std::max(1.0f,activeClip.framerate);
                for(const auto& notif:activeClip.notifications){
                    ImU32 notifCol=IM_COL32(200,200,220,160);
                    switch(notif.kind){
                        case scene::NotetrackKind::Fire:
                        case scene::NotetrackKind::MuzzleFlash:
                            notifCol=IM_COL32(255,140,30,190); break;
                        case scene::NotetrackKind::EjectBrass:
                        case scene::NotetrackKind::DropClip:
                        case scene::NotetrackKind::ClipIn:
                            notifCol=IM_COL32(0,220,255,190); break;
                        case scene::NotetrackKind::Rechamber:
                            notifCol=IM_COL32(80,240,120,190); break;
                        case scene::NotetrackKind::Sound:
                        case scene::NotetrackKind::Footstep:
                            notifCol=IM_COL32(255,230,80,190); break;
                        default: break;
                    }
                    for(const auto frame:notif.frames){
                        const float notifTime=static_cast<float>(frame)/clipFps;
                        const float notifX=timeToX(notifTime);
                        if(notifX>=graphL&&notifX<=graphR){
                            drawList->AddLine({notifX,graphT},{notifX,graphB},notifCol,1.0f);
                            drawList->AddCircleFilled({notifX,graphT+5.0f},2.5f,notifCol);
                            if(std::abs(mousePos.x-notifX)<=4.0f&&mousePos.y>=graphT&&mousePos.y<=graphB){
                                uiHelp("Notetrack: %s\nCategory: %s\nFrame: %u (%.2fs)",notif.name.c_str(),scene::notetrackKindName(notif.kind),frame,notifTime);
                            }
                        }
                    }
                }
            }

            // Playhead
            const float playheadX=timeToX(app.takeTime);
            drawList->AddLine({playheadX,graphT},{playheadX,graphB},IM_COL32(255,60,60,255),2.0f);
            drawList->PopClipRect();

            // Interactions
            ImGui::SetCursorScreenPos({graphL,graphT});
            ImGui::InvisibleButton("##graph_canvas_interact",ImVec2(graphW,graphH));
            const bool isHovered=ImGui::IsItemHovered();
            auto& io=ImGui::GetIO();

            // AE Zoom & Pan
            if(isHovered){
                if(io.KeyAlt&&std::abs(io.MouseWheel)>0.01f){
                    app.graphZoomY=std::clamp(app.graphZoomY*(io.MouseWheel>0?1.2f:0.833f),0.05f,50.0f);
                }else if(io.KeyCtrl&&std::abs(io.MouseWheel)>0.01f){
                    app.graphZoomX=std::clamp(app.graphZoomX*(io.MouseWheel>0?1.2f:0.833f),0.05f,50.0f);
                }
            }

            if(ImGui::IsMouseDragging(ImGuiMouseButton_Middle)||(io.KeyAlt&&ImGui::IsMouseDragging(ImGuiMouseButton_Left)&&app.graphDraggingNodeIndex<0&&app.graphDraggingHandle<0)){
                app.graphPanX+=(io.MouseDelta.x/graphW)*viewDurSpan;
                app.graphPanY-=(io.MouseDelta.y/graphH)*viewValSpan;
            }

            // Keyframe point selection, handle dragging, and time scrubbing
            if(ImGui::IsMouseClicked(ImGuiMouseButton_Left)&&isHovered){
                if(clickedHandleIdx>=0){
                    app.graphDraggingHandle=clickedHandleIdx;
                    app.graphDraggingHandleNode=clickedHandleNode;
                    app.graphDraggingHandleChannel=clickedHandleChannel;
                    app.selectedCampathNode=clickedHandleNode;
                }else if(clickedNodeIdx>=0){
                    app.selectedCampathNode=clickedNodeIdx;
                    app.graphDraggingNodeIndex=clickedNodeIdx;
                    app.graphDraggingChannelIndex=clickedChannelIdx;
                }else if(!io.KeyAlt){
                    app.graphDraggingNodeIndex=-1;
                    app.graphDraggingChannelIndex=-1;
                    app.graphDraggingHandle=-1;
                    app.takeTime=std::clamp(xToTime(mousePos.x),0.0f,duration);
                    app.takePlaying=false;
                    app.takePreview=true;
                }
            }

            if(app.graphDraggingHandle>=0&&ImGui::IsMouseDown(ImGuiMouseButton_Left)){
                if(app.graphDraggingHandleNode>=0&&app.graphDraggingHandleNode<static_cast<int>(keys.size())){
                    auto& node=keys[app.graphDraggingHandleNode];
                    const float newVal=yToVal(mousePos.y);
                    if(app.graphDraggingHandleChannel>=0){
                        setChannelVal(node,app.graphDraggingHandleChannel,newVal);
                    }
                    app.takePreview=true;
                }
            }else if(app.graphDraggingNodeIndex>=0&&ImGui::IsMouseDown(ImGuiMouseButton_Left)){
                if(app.graphDraggingNodeIndex<static_cast<int>(keys.size())){
                    auto& node=keys[app.graphDraggingNodeIndex];
                    const float newT=std::clamp(xToTime(mousePos.x),0.0f,duration);
                    const float newVal=yToVal(mousePos.y);
                    node.tick=static_cast<std::uint32_t>(std::clamp(std::round(newT*sampleRate),0.0f,duration*sampleRate));
                    if(app.graphDraggingChannelIndex>=0){
                        setChannelVal(node,app.graphDraggingChannelIndex,newVal);
                    }
                    std::sort(keys.begin(),keys.end(),[](const auto& a,const auto& b){return a.tick<b.tick;});
                    for(std::size_t i=0;i<keys.size();++i){
                        if(keys[i].tick==node.tick){
                            app.selectedCampathNode=static_cast<int>(i);
                            app.graphDraggingNodeIndex=static_cast<int>(i);
                            break;
                        }
                    }
                    app.takeTime=newT;
                    app.takePlaying=false;
                    app.takePreview=true;
                }
            }else if(!ImGui::IsMouseDown(ImGuiMouseButton_Left)){
                app.graphDraggingNodeIndex=-1;
                app.graphDraggingChannelIndex=-1;
                app.graphDraggingHandle=-1;
                app.graphDraggingHandleNode=-1;
                app.graphDraggingHandleChannel=-1;
            }else if(ImGui::IsItemActive()&&app.graphDraggingNodeIndex<0&&app.graphDraggingHandle<0&&!io.KeyAlt){
                app.takeTime=std::clamp(xToTime(mousePos.x),0.0f,duration);
                app.takePlaying=false;
                app.takePreview=true;
            }
        }
    }
    ImGui::EndChild();
    ImGui::PopStyleColor();
}

