        if(!smokeTest&&!pngSmokeTest&&cadence::replay::pauseForInactiveWindow(windowFocused,windowMinimized,captureInProgress)){diagnostic::phase(diagnostic::Phase::Unfocused);if(app.workspaceMode!=2)processCatalogScan(app);glfwWaitEventsTimeout(0.016);continue;}
        processDeferredActorCapture(app);
        ImGui_ImplOpenGL3_NewFrame();
        ImGui_ImplGlfw_NewFrame();
        // Minimized GLFW windows report zero size. Keep the last UI layout so
        // the offscreen capture viewport still executes at its intended size.
        {auto& io=ImGui::GetIO();if(io.DisplaySize.x>0&&io.DisplaySize.y>0)lastUsableDisplaySize=io.DisplaySize;else if(captureInProgress)io.DisplaySize=lastUsableDisplaySize;}
        // GLFW owns relative gameplay input.  Do not let ImGui see the hidden
        // virtual cursor or buttons while captured: GLFW_CURSOR_DISABLED can
        // move that virtual position beyond the viewport even though Windows
        // draws no cursor, which otherwise hovers and edits inspector widgets.
        {auto& io=ImGui::GetIO();if(app.actorInputCaptured){io.ConfigFlags|=ImGuiConfigFlags_NoMouse;io.MousePos={-std::numeric_limits<float>::max(),-std::numeric_limits<float>::max()};for(bool& down:io.MouseDown)down=false;io.MouseWheel=0;io.MouseWheelH=0;}else io.ConfigFlags&=~ImGuiConfigFlags_NoMouse;}
        ImGui::NewFrame();
        if(app.workspaceMode!=2&&!app.takePreview&&app.dayNight.enabled&&(app.dayNight.running||app.dayNight.starAutoRotate)&&app.playing)app.dayNightSeconds+=std::max(0.f,ImGui::GetIO().DeltaTime*app.playbackSpeed);
        if(app.workspaceMode!=2&&!app.takePreview&&app.water.enabled&&app.water.animate&&app.playing)app.waterSeconds+=std::max(0.f,ImGui::GetIO().DeltaTime*app.playbackSpeed);
#ifdef _WIN32
        const bool winF1 = windowFocused && (GetAsyncKeyState(VK_F1) & 0x8000) != 0;
#else
        const bool winF1 = false;
#endif
        const bool f1Key = actorKey(app, GLFW_KEY_F1) || ImGui::IsKeyPressed(ImGuiKey_F1, false) || winF1;
        const bool graveKey = actorKey(app, GLFW_KEY_GRAVE_ACCENT) || ImGui::IsKeyPressed(ImGuiKey_GraveAccent, false);
        const bool captureHotkey = f1Key || (graveKey && !ImGui::GetIO().WantTextInput);
        if(captureHotkey && !app.previousF1Key&&app.workspaceMode!=2){
            toggleGlobalGameplayCapture(app);
        }
        app.previousF1Key = f1Key || graveKey;
        if(app.workspaceMode!=2&&!ImGui::GetIO().WantTextInput){if(ImGui::IsKeyPressed(ImGuiKey_F5,false))toggleTakeRecording(app);if(ImGui::IsKeyPressed(ImGuiKey_F6,false)){if(app.takeRecording)discardTakeRecording(app);else toggleTakePlayback(app);}if(ImGui::IsKeyPressed(ImGuiKey_F7,false)){returnToLiveGameplay(app);}}
        if(app.workspaceMode!=2)handleTakeCameraInput(app,ImGui::GetIO().DeltaTime);
        diagnostic::phase(diagnostic::Phase::Catalog);if(app.workspaceMode!=2)processCatalogScan(app);
        if(app.workspaceMode!=2){
        const bool classLoaderOwnsScene=app.pendingClassLoadStage>=0;
        diagnostic::phase(diagnostic::Phase::ClassLoad);processPendingClassLoad(app);
        diagnostic::phase(diagnostic::Phase::MapLoad);processPendingMapLoad(app);
        if(!classLoaderOwnsScene){diagnostic::phase(diagnostic::Phase::ModelLoad);processPendingModelLoad(app);diagnostic::phase(diagnostic::Phase::AnimationLoad);processPendingAnimationLoad(app);}
        }
        diagnostic::phase(diagnostic::Phase::Ui);const auto uiBuildStart=std::chrono::steady_clock::now();drawUi(app);const auto traceUiEnd=std::chrono::steady_clock::now();app.performanceUiTotalMs=app.performanceUiTotalMs*.9+std::chrono::duration<double,std::milli>(traceUiEnd-uiBuildStart).count()*.1;
        diagnostic::phase(diagnostic::Phase::UiFinalize);
        if(app.workspaceMode!=2){drawCatalogGamePrompt(app);drawC2mPromptModal(app);}
        ImGui::Render();
        int width{}, height{};
        glfwGetFramebufferSize(window, &width, &height);
        glViewport(0, 0, width, height);
        glClearColor(0.055f, 0.065f, 0.08f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT);
        diagnostic::phase(diagnostic::Phase::UiDraw);const auto uiDrawStart=std::chrono::steady_clock::now();ImGui_ImplOpenGL3_RenderDrawData(ImGui::GetDrawData());const auto traceDrawEnd=std::chrono::steady_clock::now();app.performanceUiDrawMs=app.performanceUiDrawMs*.9+std::chrono::duration<double,std::milli>(traceDrawEnd-uiDrawStart).count()*.1;
        if(benchmarkCheck&&benchui::workspace&&width>0&&height>0){std::vector<std::uint8_t> pixels(static_cast<std::size_t>(width)*height*4);glReadPixels(0,0,width,height,GL_RGBA,GL_UNSIGNED_BYTE,pixels.data());std::string error;if(!app.renderer.savePixelsPng(benchui::workspace->reportDir/"workspace.png",width,height,pixels,error)){std::cerr<<error;result=1;}}
        diagnostic::phase(diagnostic::Phase::Present);const auto swapStart=std::chrono::steady_clock::now();glfwSwapBuffers(window);const auto traceEnd=std::chrono::steady_clock::now();app.performanceSwapMs=app.performanceSwapMs*.9+std::chrono::duration<double,std::milli>(traceEnd-swapStart).count()*.1;
        if(diagnostic::active){
            const auto ms=[](auto d){return std::chrono::duration<double,std::milli>(d).count();};
            traceFrames.add(ms(traceEnd-traceStart),ms(uiBuildStart-traceStart),ms(traceUiEnd-uiBuildStart),ms(uiDrawStart-traceUiEnd),ms(traceDrawEnd-uiDrawStart),ms(traceEnd-swapStart));
            const double now=diagnostic::active->seconds();
            if(now>=traceFrames.nextSample){
                const auto stats=app.renderer.renderStats(false);std::ostringstream line;line<<traceFrames.summary()<<" gpu_delayed_ms="<<app.renderer.gpuFrameMilliseconds()<<" render_cpu_ema_ms="<<app.performanceRenderMs<<" bots_cpu_ema_ms="<<app.performanceBotMs<<" bots="<<app.bots.size()<<" clips="<<app.scene.animations.size()<<" bot_clips="<<app.botAnimationClipCount<<" rig_meshes="<<app.scene.meshes.size()<<" textures="<<stats.loadedTextureCount<<" estimated_vram_bytes="<<stats.estimatedVramBytes<<" draws="<<stats.lastTotalDrawCalls<<" framebuffer="<<width<<'x'<<height<<" debug_view="<<app.renderDebugView<<" dof="<<app.dof.enabled<<" hbao="<<app.hbao.enabled<<" playing="<<app.playing<<" timescale="<<app.playbackSpeed<<" pending_class="<<app.pendingClassLoadStage<<" pending_model="<<app.pendingModelKind<<" pending_map="<<app.pendingMapFuture.has_value()<<" pending_catalog="<<app.catalogScanFuture.has_value()<<" animation_queue="<<app.pendingAnimationCursor<<'/'<<app.pendingAnimationFiles.size();
#ifdef _WIN32
                FILETIME created{},exited{},kernel{},user{};IO_COUNTERS io{};PROCESS_MEMORY_COUNTERS memory{};
                if(GetProcessTimes(GetCurrentProcess(),&created,&exited,&kernel,&user)){const auto ticks=[](FILETIME t){return (static_cast<std::uint64_t>(t.dwHighDateTime)<<32)|t.dwLowDateTime;};line<<" process_cpu_total_ms="<<(ticks(kernel)+ticks(user))/10000;}
                if(GetProcessIoCounters(GetCurrentProcess(),&io))line<<" io_read_total="<<io.ReadTransferCount<<" io_write_total="<<io.WriteTransferCount;
                if(K32GetProcessMemoryInfo(GetCurrentProcess(),&memory,sizeof(memory)))line<<" working_set="<<memory.WorkingSetSize<<" committed="<<memory.PagefileUsage;
#endif
                diagnostic::event(line.str());traceFrames={};traceFrames.nextSample=now+1;
                if(traceGpuMemory&&now>=traceNextGpuMemory){
                    const auto begin=std::chrono::steady_clock::now();GLint freeKb{},totalKb{},evictions{},evictedKb{};
                    glGetIntegerv(0x9047,&totalKb);glGetIntegerv(0x9049,&freeKb);glGetIntegerv(0x904A,&evictions);glGetIntegerv(0x904B,&evictedKb);
                    diagnostic::event("GPU MEMORY: total_kb="+std::to_string(totalKb)+" free_kb="+std::to_string(freeKb)+" evictions="+std::to_string(evictions)+" evicted_kb="+std::to_string(evictedKb)+" query_ms="+std::to_string(ms(std::chrono::steady_clock::now()-begin)));
                    traceNextGpuMemory=now+10;
                }
                if(traceStatus!=app.status){traceStatus=app.status;diagnostic::event("STATUS: "+traceStatus);}
                if(traceBotCount!=app.bots.size()){traceBotCount=app.bots.size();diagnostic::event("BOT COUNT: "+std::to_string(traceBotCount));}
            }
        }
